import std.collection.*
import std.time.DateTime

class AccessGatewayFilter {
    /*
    This class is a filter used for accessing gateway filtering, primarily for authentication and access log recording.
    */

    public init() {
    }

    public func filter(request: HashMap<String, Any>): Bool {
        let uri = request.get("path") ?? ""
        let method = request.get("method") ?? ""

        // Allow all /login POST requests
        if (uri == "/login" && method == "POST") {
            return true
        }

        // Check if URI starts with allowed prefixes
        if (!is_start_with(uri)) {
            return false
        }

        // Validate JWT and get user
        let userOpt = get_jwt_user(request)
        if (userOpt is None) {
            return false
        }

        let user = userOpt.getOrThrow()
        set_current_user_info_and_log(user)

        return true
    }

    public func is_start_with(request_uri: String): Bool {
        request_uri.startsWith("/api") || request_uri.startsWith("/login")
    }

    public func get_jwt_user(request: HashMap<String, Any>): Option<HashMap<String, Any>> {
        let headersOpt = request.get("headers")
        if (headersOpt is None) {
            return None<HashMap<String, Any>>()
        }

        let headers = headersOpt as HashMap<String, Any>
        let authOpt = headers.get("Authorization")
        if (authOpt is None) {
            return None<HashMap<String, Any>>()
        }

        let auth = authOpt as HashMap<String, Any>
        let jwtOpt = auth.get("jwt")
        let userOpt = auth.get("user")

        if (jwtOpt is None || userOpt is None) {
            return None<HashMap<String, Any>>()
        }

        let jwt = jwtOpt as String
        let user = userOpt as HashMap<String, Any>

        // Validate JWT (simple validation: check if it contains current date)
        let currentDate = DateTime.now().format("yyyy-MM-dd")
        if (!jwt.contains(currentDate)) {
            return None<HashMap<String, Any>>()
        }

        return Some(user)
    }

    public func set_current_user_info_and_log(user: HashMap<String, Any>): Unit {
        // In a real implementation, you would store user info in a context/thread-local storage
        // and write to a log file or system. Here we just print it.

        let name = user.get("name") ?? "unknown"
        let address = user.get("address") ?? "unknown"
        let timestamp = DateTime.now().format("yyyy-MM-dd HH:mm:ss")

        println("Access Log [${timestamp}] User: ${name}, Address: ${address}")
    }
}

