    } else if (type_info.isSubtypeOf(TypeInfo.of<Float64>())) {
        return Float64.fromString(value) ?? value
    } else if (type_info.isSubtypeOf(TypeInfo.of<Bool>())) {
        return value == "true" || value == "True"
    } else {
        return value
    }
}

