        var totalScore: Int64 = 0
        var studentCount: Int64 = 0

        for ((_, student) in this.students) {
            if (student.cources.contains(course)) {
                totalScore += student.cources[course]
                studentCount += 1
            }
        }

        if (studentCount == 0) {
            return None<Float64>
        }

        return Some<Float64>(Float64(totalScore) / Float64(studentCount))
    }

    public func get_top_student(): Option<String> {
        /*
        Calculate every student's gpa with get_gpa method, and find the student with highest gpa
        :return: String, name of student whose gpa is highest
