        [{'Chord': 'C', 'Tune': '53231323'}, {'Chord': 'Em', 'Tune': '43231323'}, {'Chord': 'F', 'Tune': '43231323'}, {'Chord': 'G', 'Tune': '63231323'}]

        */
        var result = ArrayList<HashMap<String, String>>()
        let trimmed_text = play_text.trim()
        if (trimmed_text.isEmpty()) {
            return result
        }

        let tokens = trimmed_text.split(separator: ' ')
        for (token in tokens) {
            let chord_and_tune = split_chord_and_tune(token)
            let chord = chord_and_tune[0]
            let tune = chord_and_tune[1]

            let map = HashMap<String, String>()
            map.add("Chord", chord)
            map.add("Tune", tune)
            result.add(map)

            if (display) {
                println(this.display(chord, tune))
            }
        }

        return result
    }

    // Helper method to split chord and tune from a token
    private func split_chord_and_tune(token: String): Array<String> {
        var index = 0
        let runes = token.toRuneArray()
        while (index < runes.size && !is_digit(runes[index])) {
            index += 1
        }
        let chord = token.substring(0, index)
        let tune = token.substring(index)
        return [chord, tune]
    }

    // Helper method to check if a rune is a digit
    private func is_digit(r: Rune): Bool {
        let char = r.toString()
        return char >= "0" && char <= "9"
    }

    public func display(key: String, value: String): String {
        /*
        Print out chord and play tune with following format: Normal Guitar Playing -- Chord: %s, Play Tune: %s
