class BigNumCalculator {

    /*
    This is a class that implements big number calculations, including adding, subtracting and multiplying.
    */

    public static func add(num1: String, num2: String): String {
        /*
        Adds two big numbers.
        :param num1: The first number to add,String.
        :param num2: The second number to add,String.
        :return: The sum of the two numbers,String.
        >>> BigNumCalculator.add("12345678901234567890", "98765432109876543210")
        '111111111011111111100'

        */
        return calculate(num1, num2, operation: "add")
    }

    public static func subtract(num1: String, num2: String): String {
        /*
        Subtracts two big numbers.
        :param num1: The first number to subtract,String.
        :param num2: The second number to subtract,String.
        :return: The difference of the two numbers,String.
        >>> BigNumCalculator.subtract("12345678901234567890", "98765432109876543210")
        '-86419753208641975320'

        */
        return calculate(num1, num2, operation: "subtract")
    }

    public static func multiply(num1: String, num2: String): String {
        /*
        Multiplies two big numbers.
        :param num1: The first number to multiply,String.
        :param num2: The second number to multiply,String.
        :return: The product of the two numbers,String.
        >>> BigNumCalculator.multiply("12345678901234567890", "98765432109876543210")
        '1219326311370217952237463801111263526900'

        */
        return calculate(num1, num2, operation: "multiply")
    }

    private static func calculate(num1: String, num2: String, operation: String): String {
        var result = ""
        match (operation) {
            case "add" => {
                result = performAddition(num1, num2)
            }
            case "subtract" => {
                result = performSubtraction(num1, num2)
            }
            case "multiply" => {
                result = performMultiplication(num1, num2)
            }
            case _ => {
                result = "Invalid operation"
            }
        }
        return result
    }

    private static func performAddition(num1: String, num2: String): String {
        // Remove leading zeros
        let n1 = removeLeadingZeros(num1)
        let n2 = removeLeadingZeros(num2)

        // Handle negative numbers
        if (n1.startsWith("-") && n2.startsWith("-")) {
            let abs1 = n1.substring(1)
            let abs2 = n2.substring(1)
            return "-" + performAddition(abs1, abs2)
        } else if (n1.startsWith("-")) {
            let abs1 = n1.substring(1)
            return performSubtraction(n2, abs1)
        } else if (n2.startsWith("-")) {
            let abs2 = n2.substring(1)
            return performSubtraction(n1, abs2)
        }

        // Both numbers are positive
        var result = ""
        var carry = 0
        var i = n1.size - 1
        var j = n2.size - 1

        while (i >= 0 || j >= 0 || carry > 0) {
            let digit1 = if (i >= 0) { parseDigit(n1[i]) } else { 0 }
            let digit2 = if (j >= 0) { parseDigit(n2[j]) } else { 0 }
            let sum = digit1 + digit2 + carry
            result = (sum % 10).toString() + result
            carry = sum / 10
            i = i - 1
            j = j - 1
        }

        return result
    }

    private static func performSubtraction(num1: String, num2: String): String {
        // Remove leading zeros
        let n1 = removeLeadingZeros(num1)
        let n2 = removeLeadingZeros(num2)

        // Handle negative numbers
        if (n1.startsWith("-") && n2.startsWith("-")) {
            let abs1 = n1.substring(1)
            let abs2 = n2.substring(1)
            return performSubtraction(abs2, abs1)
        } else if (n1.startsWith("-")) {
            let abs1 = n1.substring(1)
            return "-" + performAddition(abs1, n2)
        } else if (n2.startsWith("-")) {
            let abs2 = n2.substring(1)
            return performAddition(n1, abs2)
        }

        // Both numbers are positive
        // Check if we need to swap
        let comparison = compareMagnitude(n1, n2)
        let (larger, smaller, isNegative) = if (comparison >= 0) { 
            (n1, n2, false) 
        } else { 
            (n2, n1, true) 
        }

        var result = ""
        var borrow = 0
        var i = larger.size - 1
        var j = smaller.size - 1

        while (i >= 0) {
            var digit1 = parseDigit(larger[i]) - borrow
            let digit2 = if (j >= 0) { parseDigit(smaller[j]) } else { 0 }

            if (digit1 < digit2) {
                digit1 = digit1 + 10
                borrow = 1
            } else {
                borrow = 0
            }

            result = ((digit1 - digit2) % 10).toString() + result
            i = i - 1
            j = j - 1
        }

        result = removeLeadingZeros(result)
        return if (isNegative && result != "0") { "-" + result } else { result }
    }

    private static func performMultiplication(num1: String, num2: String): String {
        // Remove leading zeros
        let n1 = removeLeadingZeros(num1)
        let n2 = removeLeadingZeros(num2)

        // Handle negative numbers
        let isNegative = (n1.startsWith("-") && !n2.startsWith("-")) || 
                         (!n1.startsWith("-") && n2.startsWith("-"))

        let abs1 = if (n1.startsWith("-")) { n1.substring(1) } else { n1 }
        let abs2 = if (n2.startsWith("-")) { n2.substring(1) } else { n2 }

        if (abs1 == "0" || abs2 == "0") {
            return "0"
        }

        var result = "0"
        var multiplier = ""

        for (i in 0..abs2.size) {
            let digit = parseDigit(abs2[abs2.size - 1 - i])
            if (digit != 0) {
                var partial = abs1
                // Multiply by digit
                partial = multiplyByDigit(partial, digit)
                // Add trailing zeros
                partial = partial + multiplier
                // Add to result
                result = performAddition(result, partial)
            }
            multiplier = multiplier + "0"
        }

        return if (isNegative && result != "0") { "-" + result } else { result }
    }

    private static func multiplyByDigit(num: String, digit: Int64): String {
        if (digit == 0) {
            return "0"
        }

        var result = ""
        var carry = 0
        var i = num.size - 1

        while (i >= 0 || carry > 0) {
            let d = if (i >= 0) { parseDigit(num[i]) } else { 0 }
            let product = d * digit + carry
            result = (product % 10).toString() + result
            carry = product / 10
            i = i - 1
        }

        return result
    }

    private static func parseDigit(r: Rune): Int64 {
        match (r) {
            case r'0' => 0
            case r'1' => 1
            case r'2' => 2
            case r'3' => 3
            case r'4' => 4
            case r'5' => 5
            case r'6' => 6
            case r'7' => 7
            case r'8' => 8
            case r'9' => 9
            case _ => 0
        }
    }

    private static func removeLeadingZeros(num: String): String {
        if (num.size == 0) {
            return "0"
        }

        var start = 0
        let isNegative = num.startsWith("-")
        let offset = if (isNegative) { 1 } else { 0 }

        while (start + offset < num.size && num[start + offset] == r'0') {
            start = start + 1
        }

        if (start + offset >= num.size) {
            return "0"
        }

        return if (isNegative) { "-" + num.substring(start + offset) } else { num.substring(start) }
    }

    private static func compareMagnitude(num1: String, num2: String): Int64 {
        if (num1.size != num2.size) {
            return if (num1.size > num2.size) { 1 } else { -1 }
        }

        for (i in 0..num1.size) {
            let d1 = parseDigit(num1[i])
            let d2 = parseDigit(num2[i])
            if (d1 != d2) {
                return if (d1 > d2) { 1 } else { -1 }
            }
        }

        return 0
    }
}

