class BigNumCalculator {

    /*
    This is a class that implements big number calculations, including adding, subtracting and multiplying.
    */

    public static func add(num1: String, num2: String): String {
        /*
        Adds two big numbers.
        :param num1: The first number to add,String.
        :param num2: The second number to add,String.
        :return: The sum of the two numbers,String.
        >>> BigNumCalculator.add("12345678901234567890", "98765432109876543210")
        '111111111011111111100'

        */
        let n1 = parseNonNegative(num1)
        let n2 = parseNonNegative(num2)
        let sign1 = if (num1[0] == '-') { -1 } else { 1 }
        let sign2 = if (num2[0] == '-') { -1 } else { 1 }

        if (sign1 == sign2) {
            let result = addNonNegative(n1, n2)
            return if (sign1 == -1 && result != "0") { "-" + result } else { result }
        } else {
            let cmp = compareNonNegative(n1, n2)
            if (cmp == 0) {
                return "0"
            } else if (cmp > 0) {
                let result = subtractNonNegative(n1, n2)
                return if (sign1 == -1) { "-" + result } else { result }
            } else {
                let result = subtractNonNegative(n2, n1)
                return if (sign2 == -1) { "-" + result } else { result }
            }
        }
    }

    public static func subtract(num1: String, num2: String): String {
        /*
        Subtracts two big numbers.
        :param num1: The first number to subtract,String.
        :param num2: The second number to subtract,String.
        :return: The difference of the two numbers,String.
        >>> BigNumCalculator.subtract("12345678901234567890", "98765432109876543210")
        '-86419753208641975320'

        */
        let negNum2 = if (num2[0] == '-') { num2.substring(1) } else { "-" + num2 }
        return add(num1, negNum2)
    }

    public static func multiply(num1: String, num2: String): String {
        /*
        Multiplies two big numbers.
        :param num1: The first number to multiply,String.
        :param num2: The second number to multiply,String.
        :return: The product of the two numbers,String.
        >>> BigNumCalculator.multiply("12345678901234567890", "98765432109876543210")
        '1219326311370217952237463801111263526900'

        */
        let n1 = parseNonNegative(num1)
        let n2 = parseNonNegative(num2)
        let sign1 = if (num1[0] == '-') { -1 } else { 1 }
        let sign2 = if (num2[0] == '-') { -1 } else { 1 }
        let resultSign = sign1 * sign2

        let result = multiplyNonNegative(n1, n2)
        return if (resultSign == -1 && result != "0") { "-" + result } else { result }
    }

    // ---------------- Helper functions ----------------

    // Parses a number string to remove sign and leading zeros
    static func parseNonNegative(num: String): String {
        let start = if (num[0] == '-' || num[0] == '+') { 1 } else { 0 }
        var i = start
        while (i < num.size && num[i] == '0') { i += 1 }
        if (i == num.size) { return "0" }
        return num.substring(i)
    }

    // Compares two non-negative numbers represented as strings.
    // Returns -1 if a < b, 0 if a == b, 1 if a > b
    static func compareNonNegative(a: String, b: String): Int8 {
        if (a.size < b.size) { return -1 }
        if (a.size > b.size) { return 1 }
        for (i in 0..a.size) {
            if (a[i] < b[i]) { return -1 }
            if (a[i] > b[i]) { return 1 }
        }
        return 0
    }

    // Adds two non-negative number strings
    static func addNonNegative(num1: String, num2: String): String {
        var i = num1.size - 1
        var j = num2.size - 1
        var carry: UInt8 = 0
        var result = ArrayList<Rune>()

        while (i >= 0 || j >= 0 || carry > 0) {
            let digit1 = if (i >= 0) { UInt8(num1[i] - '0') } else { 0 }
            let digit2 = if (j >= 0) { UInt8(num2[j] - '0') } else { 0 }
            let sum = digit1 + digit2 + carry
            result.add(0, Rune('0' + (sum % 10)))
            carry = sum / 10
            i -= 1
            j -= 1
        }

        var resStr = ""
        for (r in result) {
            resStr += String(r)
        }
        return resStr
    }

    // Subtracts two non-negative number strings (assumes num1 >= num2)
    static func subtractNonNegative(num1: String, num2: String): String {
        var i = num1.size - 1
        var j = num2.size - 1
        var borrow: Int8 = 0
        var result = ArrayList<Rune>()

        while (i >= 0) {
            var digit1 = Int8(num1[i] - '0') - borrow
            let digit2 = if (j >= 0) { Int8(num2[j] - '0') } else { 0 }

            if (digit1 < digit2) {
                digit1 += 10
                borrow = 1
            } else {
                borrow = 0
            }

            result.add(0, Rune('0' + UInt8(digit1 - digit2)))
            i -= 1
            j -= 1
        }

        // Remove leading zeros
        var start = 0
        while (start < result.size - 1 && result[start] == r'0') {
            start += 1
        }

        var resStr = ""
        for (k in start..result.size) {
            resStr += String(result[k])
        }
        return resStr
    }

    // Multiplies two non-negative number strings
    static func multiplyNonNegative(num1: String, num2: String): String {
        if (num1 == "0" || num2 == "0") {
            return "0"
        }

        let n1 = num1.size
        let n2 = num2.size
        var result = ArrayList<UInt8>([0; n1 + n2])

        for (i in 0..n1) {
            for (j in 0..n2) {
                let digit1 = UInt8(num1[n1 - 1 - i] - '0')
                let digit2 = UInt8(num2[n2 - 1 - j] - '0')
                let mul = digit1 * digit2
                let p1 = i + j
                let p2 = i + j + 1
                let sum = mul + result[p2]

                result[p2] = sum % 10
                result[p1] += sum / 10
            }
        }

        // Skip leading zeros
        var start = 0
        while (start < result.size && result[start] == 0) {
            start += 1
        }

        if (start == result.size) {
            return "0"
        }

        var s = ""
        for (i in start..result.size) {
            s += String(Rune('0' + result[i]))
        }
        return s
    }
}

