class BigNumCalculator {

    /*
    This is a class that implements big number calculations, including adding, subtracting and multiplying.
    */

    public static func add(num1: String, num2: String): String {
        /*
        Adds two big numbers.
        :param num1: The first number to add,String.
        :param num2: The second number to add,String.
        :return: The sum of the two numbers,String.
        >>> BigNumCalculator.add("12345678901234567890", "98765432109876543210")
        '111111111011111111100'

        */
        let n1 = num1.toRuneArray()
        let n2 = num2.toRuneArray()
        var result = ArrayList<Rune>()
        var i = n1.size - 1
        var j = n2.size - 1
        var carry = 0

        while (i >= 0 || j >= 0 || carry > 0) {
            let digit1 = if (i >= 0) { (n1[i] - r'0').toInt() } else { 0 }
            let digit2 = if (j >= 0) { (n2[j] - r'0').toInt() } else { 0 }
            let sum = digit1 + digit2 + carry
            result.add(0, r'0' + Rune(sum % 10))
            carry = sum / 10
            i -= 1
            j -= 1
        }

        return String.fromRunes(result.iterator())
    }

    public static func subtract(num1: String, num2: String): String {
        /*
        Subtracts two big numbers.
        :param num1: The first number to subtract,String.
        :param num2: The second number to subtract,String.
        :return: The difference of the two numbers,String.
        >>> BigNumCalculator.subtract("12345678901234567890", "98765432109876543210")
        '-86419753208641975320'

        */
        let n1 = num1.toRuneArray()
        let n2 = num2.toRuneArray()

        // Determine which number is larger
        let isNegative = if (n1.size < n2.size) {
            true
        } else if (n1.size > n2.size) {
            false
        } else {
            var k = 0
            while (k < n1.size && n1[k] == n2[k]) {
                k += 1
            }
            if (k < n1.size && n1[k] < n2[k]) {
                true
            } else {
                false
            }
        }

        // Ensure we're subtracting smaller from larger
        let (larger, smaller) = if (isNegative) { (n2, n1) } else { (n1, n2) }

        var result = ArrayList<Rune>()
        var i = larger.size - 1
        var j = smaller.size - 1
        var borrow = 0

        while (i >= 0) {
            let digit1 = (larger[i] - r'0').toInt() - borrow
            let digit2 = if (j >= 0) { (smaller[j] - r'0').toInt() } else { 0 }

            let diff = if (digit1 >= digit2) {
                borrow = 0
                digit1 - digit2
            } else {
                borrow = 1
                digit1 + 10 - digit2
            }

            result.add(0, r'0' + Rune(diff))
            i -= 1
            j -= 1
        }

        // Remove leading zeros
        while (result.size > 1 && result[0] == r'0') {
            result.remove(at: 0)
        }

        // Add negative sign if needed
        if (isNegative) {
            result.add(0, r'-')
        }

        return String.fromRunes(result.iterator())
    }

    public static func multiply(num1: String, num2: String): String {
        /*
        Multiplies two big numbers.
        :param num1: The first number to multiply,String.
        :param num2: The second number to multiply,String.
        :return: The product of the two numbers,String.
        >>> BigNumCalculator.multiply("12345678901234567890", "98765432109876543210")
        '1219326311370217952237463801111263526900'

        */
        // Handle zero case
        if (num1 == "0" || num2 == "0") {
            return "0"
        }

        let n1 = num1.toRuneArray()
        let n2 = num2.toRuneArray()
        let len1 = n1.size
        let len2 = n2.size
        var result = ArrayList<Int64>([0] * (len1 + len2))

        // Multiply each digit
        for (i in (0..len1).reversed()) {
            for (j in (0..len2).reversed()) {
                let digit1 = (n1[i] - r'0').toInt()
                let digit2 = (n2[j] - r'0').toInt()
                let mul = digit1 * digit2
                let pos1 = i + j
                let pos2 = i + j + 1
                let sum = mul + result[pos2]

                result[pos2] = sum % 10
                result[pos1] += sum / 10
            }
        }

        // Convert to string, skipping leading zeros
        var builder = ArrayList<Rune>()
        var started = false
        for (i in 0..result.size) {
            if (result[i] != 0) {
                started = true
            }
            if (started) {
                builder.add(r'0' + Rune(result[i]))
            }
        }

        // Handle case where result is all zeros
        if (!started) {
            return "0"
        }

        return String.fromRunes(builder.iterator())
    }
}

