        }
        if (!num1.startsWith("-") && num2.startsWith("-")) {
            return subtract(num1, num2.substring(1))
        }
        if (num1.startsWith("-") && num2.startsWith("-")) {
            return "-" + add(num1.substring(1), num2.substring(1))
        }

        // Pad the shorter number with leading zeros
        let maxLen = Math.max(num1.size, num2.size)
        var n1 = num1
        var n2 = num2
        while (n1.size < maxLen) {
            n1 = "0" + n1
        }
        while (n2.size < maxLen) {
            n2 = "0" + n2
        }

        var result = ""
        var carry = 0
        for (i in (maxLen - 1)..(-1):(-1)) {
            let digit1 = n1[i].toString().toInt()
            let digit2 = n2[i].toString().toInt()
            let sum = digit1 + digit2 + carry
            result = (sum % 10).toString() + result
            carry = sum / 10
        }
        if (carry > 0) {
            result = carry.toString() + result
        }

        // Remove leading zeros
        while (result.size > 1 && result[0] == '0') {
            result = result.substring(1)
        }

        return result
    }

    public static func subtract(num1: String, num2: String): String {
        /*
        Subtracts two big numbers.
        :param num1: The first number to subtract,String.
        :param num2: The second number to subtract,String.
        :return: The difference of the two numbers,String.
        >>> BigNumCalculator.subtract("12345678901234567890", "98765432109876543210")
        '-86419753208641975320'

        */

        // Handle negative numbers
        if (num1.startsWith("-") && !num2.startsWith("-")) {
