        }
        if (!num1.startsWith("-") && num2.startsWith("-")) {
            return add(num1, num2.substring(1))
        }
        if (num1.startsWith("-") && num2.startsWith("-")) {
            return subtract(num2.substring(1), num1.substring(1))
        }

        // Determine which number is larger to avoid negative results during subtraction
        let isNegative = num1 < num2
        let (larger, smaller) = if (isNegative) { (num2, num1) } else { (num1, num2) }

        // Pad the smaller number with leading zeros
        let maxLen = larger.size
        var s = smaller
        while (s.size < maxLen) {
            s = "0" + s
        }

        var result = ""
        var borrow = 0
        for (i in (maxLen - 1)..(-1):(-1)) {
            let digit1 = larger[i].toString().toInt()
            let digit2 = s[i].toString().toInt()
            var diff = digit1 - digit2 - borrow
            if (diff < 0) {
                diff += 10
                borrow = 1
            } else {
                borrow = 0
            }
            result = diff.toString() + result
        }

        // Remove leading zeros
        while (result.size > 1 && result[0] == '0') {
            result = result.substring(1)
        }

        return if (isNegative && result != "0") { "-" + result } else { result }
    }

    public static func multiply(num1: String, num2: String): String {
        /*
        Multiplies two big numbers.
        :param num1: The first number to multiply,String.
        :param num2: The second number to multiply,String.
        :return: The product of the two numbers,String.
        >>> BigNumCalculator.multiply("12345678901234567890", "98765432109876543210")
        '1219326311370217952237463801111263526900'

        */

        // Handle negative numbers
        let isNegative = (num1.startsWith("-")) != (num2.startsWith("-"))
        let n1 = if (num1.startsWith("-")) { num1.substring(1) } else { num1 }
        let n2 = if (num2.startsWith("-")) { num2.substring(1) } else { num2 }

        // Initialize result array with zeros
        var result = ArrayList<Int64>([0] * (n1.size + n2.size))

        // Multiply each digit and add to the result
        for (i in (n1.size - 1)..(-1):(-1)) {
            for (j in (n2.size - 1)..(-1):(-1)) {
                let digit1 = n1[i].toString().toInt()
                let digit2 = n2[j].toString().toInt()
                let product = digit1 * digit2
                let pos1 = i + j
                let pos2 = i + j + 1
                let sum = product + result[pos2]

                result[pos2] = sum % 10
                result[pos1] += sum / 10
            }
        }

        // Convert result to string
        var resultStr = ""
        for (digit in result) {
            resultStr += digit.toString()
        }

        // Remove leading zeros
        while (resultStr.size > 1 && resultStr[0] == '0') {
            resultStr = resultStr.substring(1)
        }

        return if (isNegative && resultStr != "0") { "-" + resultStr } else { resultStr }
    }
}

