class BigNumCalculator {

    /*
    This is a class that implements big number calculations, including adding, subtracting and multiplying.
    */

    public static func add(num1: String, num2: String): String {
        // Handle signs
        let (sign1, digits1) = parseNumber(num1)
        let (sign2, digits2) = parseNumber(num2)

        if (sign1 == sign2) {
            // Same sign: add absolute values and keep the sign
            let resultDigits = addDigits(digits1, digits2)
            return formatResult(sign1, resultDigits)
        } else {
            // Different signs: subtract smaller from larger
            let cmp = compareDigits(digits1, digits2)
            if (cmp > 0) {
                let resultDigits = subtractDigits(digits1, digits2)
                return formatResult(sign1, resultDigits)
            } else if (cmp < 0) {
                let resultDigits = subtractDigits(digits2, digits1)
                return formatResult(sign2, resultDigits)
            } else {
                return "0"
            }
        }
    }

    public static func subtract(num1: String, num2: String): String {
        // Change subtraction to addition with negated num2
        let negatedNum2 = negateNumber(num2)
        return add(num1, negatedNum2)
    }

    public static func multiply(num1: String, num2: String): String {
        let (sign1, digits1) = parseNumber(num1)
        let (sign2, digits2) = parseNumber(num2)

        let resultSign = if (sign1 == sign2) { "" } else { "-" }
        let resultDigits = multiplyDigits(digits1, digits2)
        return formatResult(resultSign, resultDigits)
    }

    // Helper functions below

    private static func parseNumber(num: String): (String, Array<Int64>) {
        let chars = num.toRuneArray()
        var index = 0
        let sign = if (chars.size > 0 && (chars[0] == r'-' || chars[0] == r'+')) {
            index = 1
            if (chars[0] == r'-') { "-" } else { "" }
        } else {
            ""
        }

        var digits = Array<Int64>([])
        for (i in index..chars.size) {
            let c = chars[i]
            if (c >= r'0' && c <= r'9') {
                digits.add((c - r'0') as Int64)
            }
        }

        // Remove leading zeros
        while (digits.size > 1 && digits[0] == 0) {
            digits.remove(at: 0)
        }

        return (sign, digits)
    }

    private static func negateNumber(num: String): String {
        if (num.startsWith("-")) {
            return num.substring(1)
        } else if (num.startsWith("+")) {
            return "-" + num.substring(1)
        } else {
            return "-" + num
        }
    }

    private static func addDigits(a: Array<Int64>, b: Array<Int64>): Array<Int64> {
        var i = a.size - 1
        var j = b.size - 1
        var carry = 0
        var result = Array<Int64>([])

        while (i >= 0 || j >= 0 || carry > 0) {
            let digitA = if (i >= 0) { a[i] } else { 0 }
            let digitB = if (j >= 0) { b[j] } else { 0 }
            let sum = digitA + digitB + carry
            result.add(0, sum % 10)
            carry = sum / 10
            i -= 1
            j -= 1
        }

        return result
    }

    private static func subtractDigits(a: Array<Int64>, b: Array<Int64>): Array<Int64> {
        // Assumes a >= b
        var i = a.size - 1
        var j = b.size - 1
        var borrow = 0
        var result = Array<Int64>([])

        while (i >= 0) {
            let digitA = a[i] - borrow
            let digitB = if (j >= 0) { b[j] } else { 0 }
            borrow = 0

            let diff = if (digitA >= digitB) {
                digitA - digitB
            } else {
                borrow = 1
                (digitA + 10) - digitB
            }

            result.add(0, diff)
            i -= 1
            j -= 1
        }

        // Remove leading zeros
        while (result.size > 1 && result[0] == 0) {
            result.remove(at: 0)
        }

        return result
    }

    private static func multiplyDigits(a: Array<Int64>, b: Array<Int64>): Array<Int64> {
        if (a.size == 1 && a[0] == 0) return [0]
        if (b.size == 1 && b[0] == 0) return [0]

        var result = Array<Int64>([0] * (a.size + b.size))

        for (i in 0..a.size) {
            for (j in 0..b.size) {
                let product = a[a.size - 1 - i] * b[b.size - 1 - j]
                let pos1 = (a.size + b.size - 1) - (i + j)
                let pos2 = pos1 - 1

                result[pos1] += product
                result[pos2] += result[pos1] / 10
                result[pos1] %= 10
            }
        }

        // Remove leading zeros
        while (result.size > 1 && result[0] == 0) {
            result.remove(at: 0)
        }

        return result
    }

    private static func compareDigits(a: Array<Int64>, b: Array<Int64>): Int64 {
        if (a.size != b.size) {
            return if (a.size > b.size) { 1 } else { -1 }
        }

        for (i in 0..a.size) {
            if (a[i] != b[i]) {
                return if (a[i] > b[i]) { 1 } else { -1 }
            }
        }

        return 0
    }

    private static func formatResult(sign: String, digits: Array<Int64>): String {
        var s = sign
        for (d in digits) {
            s += "${d}"
        }
        return s
    }
}

