        :return: The sum of the two numbers,String.
        >>> BigNumCalculator.add("12345678901234567890", "98765432109876543210")
        '111111111011111111100'

        */
        // Handle signs
        let (sign1, digits1) = BigNumCalculator.parseNumber(num1)
        let (sign2, digits2) = BigNumCalculator.parseNumber(num2)

        if (sign1 == sign2) {
            let resultDigits = BigNumCalculator.addDigits(digits1, digits2)
            return BigNumCalculator.formatResult(sign1, resultDigits)
        } else {
            let cmp = BigNumCalculator.compareDigits(digits1, digits2)
            if (cmp > 0) {
                let resultDigits = BigNumCalculator.subtractDigits(digits1, digits2)
                return BigNumCalculator.formatResult(sign1, resultDigits)
            } else if (cmp < 0) {
                let resultDigits = BigNumCalculator.subtractDigits(digits2, digits1)
                return BigNumCalculator.formatResult(if (sign2 == '+') { '-' } else { '+' }, resultDigits)
            } else {
                return "0"
            }
        }
    }

    public static func subtract(num1: String, num2: String): String {
        /*
        Subtracts two big numbers.
        :param num1: The first number to subtract,String.
        :param num2: The second number to subtract,String.
        :return: The difference of the two numbers,String.
        >>> BigNumCalculator.subtract("12345678901234567890", "98765432109876543210")
        '-86419753208641975320'

        */
        // To subtract, we negate the second number and add
        let negatedNum2 = BigNumCalculator.negate(num2)
        return BigNumCalculator.add(num1, negatedNum2)
    }

    public static func multiply(num1: String, num2: String): String {
        /*
        Multiplies two big numbers.
        :param num1: The first number to multiply,String.
        :param num2: The second number to multiply,String.
        :return: The product of the two numbers,String.
        >>> BigNumCalculator.multiply("12345678901234567890", "98765432109876543210")
        '1219326311370217952237463801111263526900'

        */
        let (sign1, digits1) = BigNumCalculator.parseNumber(num1)
        let (sign2, digits2) = BigNumCalculator.parseNumber(num2)

        let resultSign = if (sign1 == sign2) { '+' } else { '-' }
        let resultDigits = BigNumCalculator.multiplyDigits(digits1, digits2)
        return BigNumCalculator.formatResult(resultSign, resultDigits)
    }

    // Helper methods

    private static func parseNumber(s: String): (Rune, Array<Int64>) {
        let runes = s.toRuneArray()
        let sign: Rune = if (runes[0] == r'-') {
            r'-'
        } else if (runes[0] == r'+') {
            r'+'
        } else {
            r'+'
        }

        let startIdx = if (runes[0] == r'-' || runes[0] == r'+') { 1 } else { 0 }
        var digits = Array<Int64>(size = 0)
        for (i in startIdx..runes.size) {
            let digitChar = runes[i]
            let digitValue = digitChar - r'0'
            digits = digits + [Int64(digitValue)]
        }

        // Remove leading zeros
        var nonZeroStart = 0
        while (nonZeroStart < digits.size && digits[nonZeroStart] == 0) {
            nonZeroStart += 1
        }

        if (nonZeroStart == digits.size) {
            return (r'+', [0])
        }

        var cleanedDigits = Array<Int64>(size = digits.size - nonZeroStart)
        for (i in 0..cleanedDigits.size) {
            cleanedDigits[i] = digits[nonZeroStart + i]
        }

        return (sign, cleanedDigits)
    }

    private static func formatResult(sign: Rune, digits: Array<Int64>): String {
        if (digits.size == 1 && digits[0] == 0) {
            return "0"
        }

        var result = if (sign == r'-') { "-" } else { "" }
        for (d in digits) {
            result = result + String(Rune(r'0' + d))
        }
        return result
    }

    private static func addDigits(a: Array<Int64>, b: Array<Int64>): Array<Int64> {
        let maxSize = max(a.size, b.size)
        var result = Array<Int64>(size = maxSize + 1)
        var carry = 0
        var i = a.size - 1
        var j = b.size - 1
        var k = result.size - 1

        while (i >= 0 || j >= 0 || carry > 0) {
            let digitA = if (i >= 0) { a[i] } else { 0 }
            let digitB = if (j >= 0) { b[j] } else { 0 }
            let sum = digitA + digitB + carry
            result[k] = sum % 10
            carry = sum / 10
            i -= 1
            j -= 1
            k -= 1
        }

        // If the first digit is 0, remove it
        if (result[0] == 0 && result.size > 1) {
            var trimmedResult = Array<Int64>(size = result.size - 1)
            for (i in 0..trimmedResult.size) {
                trimmedResult[i] = result[i + 1]
            }
            return trimmedResult
        }

        return result
    }

    private static func subtractDigits(a: Array<Int64>, b: Array<Int64>): Array<Int64> {
        // Assumes a >= b
        var result = Array<Int64>(size = a.size)
        var borrow = 0
        var i = a.size - 1
        var j = b.size - 1
        var k = result.size - 1

        while (i >= 0) {
            let digitA = a[i]
            let digitB = if (j >= 0) { b[j] } else { 0 }
            var diff = digitA - borrow - digitB
            if (diff < 0) {
                diff += 10
                borrow = 1
            } else {
                borrow = 0
            }
            result[k] = diff
            i -= 1
            j -= 1
            k -= 1
        }

        // Remove leading zeros
        var nonZeroStart = 0
        while (nonZeroStart < result.size && result[nonZeroStart] == 0) {
            nonZeroStart += 1
        }

        if (nonZeroStart == result.size) {
            return [0]
        }

        var cleanedResult = Array<Int64>(size = result.size - nonZeroStart)
        for (i in 0..cleanedResult.size) {
            cleanedResult[i] = result[nonZeroStart + i]
        }

        return cleanedResult
    }

    private static func multiplyDigits(a: Array<Int64>, b: Array<Int64>): Array<Int64> {
        if ((a.size == 1 && a[0] == 0) || (b.size == 1 && b[0] == 0)) {
            return [0]
        }

        var result = Array<Int64>(size = a.size + b.size)

        for (i in 0..a.size) {
            for (j in 0..b.size) {
                let pos1 = a.size - 1 - i
                let pos2 = b.size - 1 - j
                let pos = result.size - 1 - (i + j)
                result[pos] += a[pos1] * b[pos2]
            }
        }

        // Handle carries
        for (i in (1..result.size).reversed()) {
            let carry = result[i] / 10
            result[i] = result[i] % 10
            result[i - 1] += carry
        }

        // Remove leading zeros
        var nonZeroStart = 0
        while (nonZeroStart < result.size && result[nonZeroStart] == 0) {
            nonZeroStart += 1
        }

        if (nonZeroStart == result.size) {
            return [0]
        }

        var cleanedResult = Array<Int64>(size = result.size - nonZeroStart)
        for (i in 0..cleanedResult.size) {
            cleanedResult[i] = result[nonZeroStart + i]
        }

        return cleanedResult
    }

    private static func compareDigits(a: Array<Int64>, b: Array<Int64>): Int64 {
        if (a.size > b.size) {
            return 1
        }
        if (a.size < b.size) {
            return -1
        }
        for (i in 0..a.size) {
            if (a[i] > b[i]) {
                return 1
            }
            if (a[i] < b[i]) {
                return -1
            }
        }
        return 0
    }

    private static func negate(s: String): String {
        if (s[0] == '-') {
            return s.substring(1)
        } else if (s[0] == '+') {
            return "-" + s.substring(1)
        } else {
            return "-" + s
        }
    }

    private static func max(a: Int64, b: Int64): Int64 {
        if (a > b) {
            return a
        }
        return b
    }

    private static func String(r: Rune): String {
        return String([r])
    }

    private static func String(runArr: Array<Rune>): String {
        var s = ""
        for (r in runArr) {
            s = s + String(r)
        }
        return s
    }

    private static func String(s: String): String {
        return s
    }

    private static func +(s1: String, s2: String): String {
        return s1 + s2
    }

    private static func +(r1: Rune, r2: Rune): Rune {
        return Rune(Int64(r1) + Int64(r2))
    }

    private static func -(r1: Rune, r2: Rune): Int64 {
        return Int64(r1) - Int64(r2)
    }

    private static func +(a1: Array<Int64>, a2: Array<Int64>): Array<Int64> {
        var result = Array<Int64>(size = a1.size + a2.size)
        var i = 0
        for (e in a1) {
            result[i] = e
            i += 1
        }
        for (e in a2) {
            result[i] = e
            i += 1
        }
        return result
    }

    private static func substring(s: String, start: Int64): String {
        let runes = s.toRuneArray()
        var resultRunes = Array<Rune>(size = runes.size - start)
        for (i in 0..resultRunes.size) {
            resultRunes[i] = runes[start + i]
        }
        return String(resultRunes)
    }
}

