        :return: The sum of the two numbers,String.
        >>> BigNumCalculator.add("12345678901234567890", "98765432109876543210")
        '111111111011111111100'

        */
        // Handle negative numbers
        if (num1.startsWith("-") && !num2.startsWith("-")) {
            return subtract(num2, num1.substring(1))
        }
        if (!num1.startsWith("-") && num2.startsWith("-")) {
            return subtract(num1, num2.substring(1))
        }
        if (num1.startsWith("-") && num2.startsWith("-")) {
            return "-" + add(num1.substring(1), num2.substring(1))
        }

        // Make both numbers the same length by padding with zeros
        let maxLen = if (num1.size > num2.size) { num1.size } else { num2.size }
        var paddedNum1 = num1
        var paddedNum2 = num2

        while (paddedNum1.size < maxLen) {
            paddedNum1 = "0" + paddedNum1
        }
        while (paddedNum2.size < maxLen) {
            paddedNum2 = "0" + paddedNum2
        }

        var result = ""
        var carry = 0

        // Add digit by digit from right to left
        for (i in 0..maxLen) {
            let idx = maxLen - 1 - i
            let digit1 = paddedNum1[idx].toString().parseOrThrow<Int64>()
            let digit2 = paddedNum2[idx].toString().parseOrThrow<Int64>()
            let sum = digit1 + digit2 + carry
            result = (sum % 10).toString() + result
            carry = sum / 10
        }

        if (carry > 0) {
            result = carry.toString() + result
        }

        // Remove leading zeros
        while (result.size > 1 && result[0] == r'0') {
            result = result.substring(1)
        }

