        }
        if (num1.startsWith("-") && num2.startsWith("-")) {
            return subtract(num2.substring(1), num1.substring(1))
        }

        // Determine if we need to swap operands
        let swap = if (num1.size < num2.size) {
            true
        } else if (num1.size == num2.size) {
            num1 < num2
        } else {
            false
        }

        let (minuend, subtrahend) = if (swap) { (num2, num1) } else { (num1, num2) }

