                      (!num1.startsWith("-") && num2.startsWith("-"))

        let absNum1 = if (num1.startsWith("-")) { num1.substring(1) } else { num1 }
        let absNum2 = if (num2.startsWith("-")) { num2.substring(1) } else { num2 }

        // Initialize result array with zeros
        let resultLen = absNum1.size + absNum2.size
        var result = Array<Int64>([Int64](repeating: 0, count: resultLen))

        // Multiply each digit of first number with each digit of second
        for (i in 0..absNum1.size) {
            let idx1 = absNum1.size - 1 - i
            let digit1 = absNum1[idx1].toString().parseOrThrow<Int64>()

            for (j in 0..absNum2.size) {
                let idx2 = absNum2.size - 1 - j
                let digit2 = absNum2[idx2].toString().parseOrThrow<Int64>()

                let pos = i + j
                let product = digit1 * digit2 + result[resultLen - 1 - pos]
                result[resultLen - 1 - pos] = product % 10
                result[resultLen - 2 - pos] += product / 10
            }
        }

        // Convert result array to string
        var resultStr = ""
        for (digit in result) {
            resultStr = resultStr + digit.toString()
        }

        // Remove leading zeros
        while (resultStr.size > 1 && resultStr[0] == r'0') {
            resultStr = resultStr.substring(1)
        }

        // Handle zero result
        if (resultStr == "") {
            resultStr = "0"
        }

        // Add negative sign if needed
        if (negative && resultStr != "0") {
            resultStr = "-" + resultStr
        }

        return resultStr
    }
}

