class BigNumCalculator {

    /*
    This is a class that implements big number calculations, including adding, subtracting and multiplying.
    */

    public static func add(num1: String, num2: String): String {
        var n1 = num1
        var n2 = num2

        // Handle negative numbers
        let negative1 = n1.startsWith("-")
        let negative2 = n2.startsWith("-")
        if (negative1) {
            n1 = n1.substring(1)
        }
        if (negative2) {
            n2 = n2.substring(1)
        }

        if (!negative1 && !negative2) {
            return addPositive(n1, n2)
        } else if (negative1 && negative2) {
            return "-" + addPositive(n1, n2)
        } else if (negative1 && !negative2) {
            // -a + b = b - a
            return subtractPositive(n2, n1)
        } else {
            // a + (-b) = a - b
            return subtractPositive(n1, n2)
        }
    }

    public static func subtract(num1: String, num2: String): String {
        var n1 = num1
        var n2 = num2

        // Handle negative numbers
        let negative1 = n1.startsWith("-")
        let negative2 = n2.startsWith("-")
        if (negative1) {
            n1 = n1.substring(1)
        }
        if (negative2) {
            n2 = n2.substring(1)
        }

        if (!negative1 && !negative2) {
            return subtractPositive(n1, n2)
        } else if (negative1 && negative2) {
            // -a - (-b) = b - a
            return subtractPositive(n2, n1)
        } else if (negative1 && !negative2) {
            // -a - b = -(a + b)
            return "-" + addPositive(n1, n2)
        } else {
            // a - (-b) = a + b
            return addPositive(n1, n2)
        }
    }

    public static func multiply(num1: String, num2: String): String {
        var n1 = num1
        var n2 = num2

        // Handle negative numbers
        let negative1 = n1.startsWith("-")
        let negative2 = n2.startsWith("-")
        if (negative1) {
            n1 = n1.substring(1)
        }
        if (negative2) {
            n2 = n2.substring(1)
        }

        let result = multiplyPositive(n1, n2)
        if ((negative1 && !negative2) || (!negative1 && negative2)) {
            if (result != "0") {
                return "-" + result
            }
        }
        return result
    }

    // Assumptions: both inputs are non-negative numbers
    private static func addPositive(num1: String, num2: String): String {
        let maxLen = max(num1.size, num2.size) + 1
        var result = ArrayList<Int64>()
        for (_ in 0..maxLen) {
            result.add(0)
        }

        var carry = 0
        var i = num1.size - 1
        var j = num2.size - 1
        var k = maxLen - 1
        while (i >= 0 || j >= 0 || carry > 0) {
            let digit1 = if (i >= 0) { Int64.parse(num1[i].toString()).getOrThrow() } else { 0 }
            let digit2 = if (j >= 0) { Int64.parse(num2[j].toString()).getOrThrow() } else { 0 }
            let sum = digit1 + digit2 + carry
            result[k] = sum % 10
            carry = sum / 10
            i -= 1
            j -= 1
            k -= 1
        }

        // Skip leading zeros
        let start = result.findFirstNotOf(0)
        if (start == -1) {
            return "0"
        }

        var finalResult = ""
        for (p in start..result.size) {
            finalResult += result[p].toString()
        }
        return finalResult
    }

    // Assumptions: both inputs are non-negative numbers
    private static func subtractPositive(num1: String, num2: String): String {
        // Compare magnitude
        let cmp = compareMagnitude(num1, num2)
        if (cmp < 0) {
            let result = subtractPositiveHelper(num2, num1)
            return "-" + result
        } else if (cmp == 0) {
            return "0"
        } else {
            return subtractPositiveHelper(num1, num2)
        }
    }

    private static func subtractPositiveHelper(larger: String, smaller: String): String {
        var result = ArrayList<Int64>()
        for (_ in 0..larger.size) {
            result.add(0)
        }

        var borrow = 0
        var i = larger.size - 1
        var j = smaller.size - 1
        var k = larger.size - 1
        while (i >= 0) {
            var digit1 = Int64.parse(larger[i].toString()).getOrThrow() - borrow
            let digit2 = if (j >= 0) { Int64.parse(smaller[j].toString()).getOrThrow() } else { 0 }
            if (digit1 < digit2) {
                digit1 += 10
                borrow = 1
            } else {
                borrow = 0
            }
            result[k] = digit1 - digit2
            i -= 1
            j -= 1
            k -= 1
        }

        // Skip leading zeros
        let start = result.findFirstNotOf(0)
        if (start == -1) {
            return "0"
        }

        var finalResult = ""
        for (p in start..result.size) {
            finalResult += result[p].toString()
        }
        return finalResult
    }

    private static func compareMagnitude(num1: String, num2: String): Int64 {
        if (num1.size < num2.size) {
            return -1
        } else if (num1.size > num2.size) {
            return 1
        } else {
            for (i in 0..num1.size) {
                let d1 = Int64.parse(num1[i].toString()).getOrThrow()
                let d2 = Int64.parse(num2[i].toString()).getOrThrow()
                if (d1 < d2) {
                    return -1
                } else if (d1 > d2) {
                    return 1
                }
            }
            return 0
        }
    }

    // Assumptions: both inputs are non-negative numbers
    private static func multiplyPositive(num1: String, num2: String): String {
        if (num1 == "0" || num2 == "0") {
            return "0"
        }

        let len1 = num1.size
        let len2 = num2.size
        var result = ArrayList<Int64>()
        for (_ in 0..(len1 + len2)) {
            result.add(0)
        }

        for (i in 0..len1) {
            for (j in 0..len2) {
                let digit1 = Int64.parse(num1[len1 - 1 - i].toString()).getOrThrow()
                let digit2 = Int64.parse(num2[len2 - 1 - j].toString()).getOrThrow()
                let product = digit1 * digit2
                let pos1 = i + j
                let pos2 = i + j + 1
                let sum = product + result[pos2]
                result[pos2] = sum % 10
                result[pos1] += sum / 10
            }
        }

        // Skip leading zeros
        let start = result.findFirstNotOf(0)
        if (start == -1) {
            return "0"
        }

        var finalResult = ""
        for (p in start..result.size) {
            finalResult += result[p].toString()
        }
        return finalResult
    }
}

