        >>> bdp.calculate_binary_info()
        {'Zeroes': 0.475, 'Ones': 0.525, 'Bit length': 40.0}

        */
        let result = HashMap<String, Float64>()
        let total_length = this.binary_string.size.toFloat64()
        var zeroes = 0
        var ones = 0

        for (char in this.binary_string.runes()) {
            if (char == r'0') {
                zeroes += 1
            } else if (char == r'1') {
                ones += 1
            }
        }

        result.add("Zeroes", (zeroes.toFloat64() / total_length))
        result.add("Ones", (ones.toFloat64() / total_length))
        result.add("Bit length", total_length)

        return result
    }

    public func convert_to_ascii(): String {
        /*
        Convert the binary string to ascii string.
        >>> bdp = BinaryDataProcessor("0110100001100101011011000110110001101111")
        >>> bdp.convert_to_ascii()
        'hello'

        */
        let runes = this.binary_string.toRuneArray()
        var result = ""
        var i = 0
        while (i < runes.size) {
            // Extract 8 bits for each character
            var byte_str = ""
            for (j in 0..8) {
