        var count_zero = 0
        for (r in this.binary_string.runes()) {
            if (r == r'0') {
                count_zero += 1
            }
        }
        let count_one = total - count_zero
        let map = HashMap<String, Float64>()
        map.add("Zeroes", (count_zero as Float64) / (total as Float64))
        map.add("Ones", (count_one as Float64) / (total as Float64))
        map.add("Bit length", total as Float64)
        return map
    }

    public func convert_to_ascii(): String {
