        Convert the binary string to ascii string.
        >>> bdp = BinaryDataProcessor("0110100001100101011011000110110001101111")
        >>> bdp.convert_to_ascii()
        'hello'

        */
        var result = ""
        let len = this.binary_string.size
        for (i in 0..len:8) {
            if (i + 8 <= len) {
                let byte_str = this.binary_string[i..i+8]
                let value = byte_str.toUInt64(radix: 2)
                result += String.fromRunes([value as Rune])
            }
        }
        return result
    }

    public func convert_to_utf8(): String {
        /*
        Convert the binary string to utf-8 string.
        >>> bdp = BinaryDataProcessor("0110100001100101011011000110110001101111")
        >>> bdp.convert_to_utf8()
        'hello'

        */
        // For ASCII-compatible strings, UTF-8 decoding is same as ASCII
        return this.convert_to_ascii()
    }
}

