        2

        */
        var i = 0
        while (i < this.patLen) {
            if (currentPos + i >= this.textLen) {
                return -1
            }
            if (this.pattern[i] != this.text[currentPos + i]) {
                return i
            }
            i = i + 1
        }
        return -1
    }

    public func bad_character_heuristic(): ArrayList<Int64> {
        /*
        Finds all occurrences of the pattern in the text.
        :return: A list of all positions of the pattern in the text, ArrayList<Int64>.
        >>> boyerMooreSearch = BoyerMooreSearch("ABAABA", "AB")
        >>> boyerMooreSearch.bad_character_heuristic()
        [0, 3]

        */
        let result = ArrayList<Int64>()
        var shift = 0
        while (shift <= (this.textLen - this.patLen)) {
            let mismatch_index = this.mismatch_in_text(shift)
            if (mismatch_index == -1) {
                result.add(shift)
                shift = shift + 1
            } else {
                let mismatch_char = this.text[shift + mismatch_index]
                let match_index = this.match_in_pattern("${mismatch_char}")
                if (match_index == -1) {
                    shift = shift + mismatch_index + 1
                } else {
                    shift = shift + mismatch_index - match_index
                }
            }
        }
        return result
    }
}

import std.collection.HashMap
import std.collection.ArrayList
import std.collection.HashSet
import std.convert.Parsable

class Calculator {

    /*
    This is a class for a calculator, capable of performing basic arithmetic calculations on numerical expressions using the operators +, -, *, /, and ^ (exponentiation).
    */

    let operators: HashMap<String, (Float64, Float64) -> Float64>

    public init() {
        /*
        Initialize the operations performed by the five operators'+','-','*','/','^'
        */
        this.operators = HashMap<String, (Float64, Float64) -> Float64>()
        operators.add("+", {x: Float64, y: Float64 => x + y})
        operators.add("-", {x: Float64, y: Float64 => x - y})
        operators.add("*", {x: Float64, y: Float64 => x * y})
        operators.add("/", {x: Float64, y: Float64 => x / y})
        operators.add("^", {x: Float64, y: Float64 => x ** y})
    }

    public func calculate(expression: String): Option<Float64> {
        /*
        Calculate the value of a given expression
        :param expression: String, given expression
        :return:If successful, returns the value of the expression; otherwise, returns None
        >>> calculator = Calculator()
        >>> calculator.calculate('1+2-3')
        0.0
        */
        var operand_stack = ArrayList<Float64>()
        var operator_stack = ArrayList<String>()
        let tokens = tokenize(expression)
        let valid_operators = HashSet<String>(["+", "-", "*", "/", "^"])

        for (token in tokens) {
            if (is_number(token)) {
                let num = parse_float(token)
                if (num is None) {
                    return None<Float64>()
                }
                operand_stack.add(num.getOrThrow())
            } else if (valid_operators.contains(token)) {
                while (!operator_stack.empty() && precedence(operator_stack[operator_stack.size - 1]) >= precedence(token)) {
                    if (operator_stack[operator_stack.size - 1] == "(") break
                    let result = apply_operator(operand_stack, operator_stack)
                    operand_stack = result[0]
                    operator_stack = result[1]
                }
                operator_stack.add(token)
            } else if (token == "(") {
                operator_stack.add(token)
            } else if (token == ")") {
                while (!operator_stack.empty() && operator_stack[operator_stack.size - 1] != "(") {
                    let result = apply_operator(operand_stack, operator_stack)
                    operand_stack = result[0]
                    operator_stack = result[1]
                }
                if (operator_stack.empty()) {
                    return None<Float64>() // Mismatched parentheses
                }
                operator_stack.remove(at: operator_stack.size - 1) // Remove '('
            } else {
                return None<Float64>() // Invalid token
            }
        }

        while (!operator_stack.empty()) {
            if (operator_stack[operator_stack.size - 1] == "(") {
                return None<Float64>() // Mismatched parentheses
            }
            let result = apply_operator(operand_stack, operator_stack)
            operand_stack = result[0]
            operator_stack = result[1]
        }

        if (operand_stack.size == 1) {
            return Some<Float64>(operand_stack[0])
        } else {
            return None<Float64>()
        }
    }

    public func precedence(op: String): Int64 {
        /*
        Returns the priority of the specified operator, where the higher the priority, the greater the assignment. The priority of '^' is greater than '/' and '*', and the priority of '/' and '*' is greater than '+' and '-'
        :param operator: String, given operator
        :return: Int64, the priority of the given operator, otherwise return 0
        >>> calculator = Calculator()
        >>> calculator.precedence('+')
        1
        >>> calculator.precedence('^')
        3
        */
        match (op) {
            case "+" => 1
            case "-" => 1
            case "*" => 2
            case "/" => 2
            case "^" => 3
            case _ => 0
        }
    }

    public func apply_operator(operand_stack: ArrayList<Float64>, operator_stack: ArrayList<String>): (ArrayList<Float64>, ArrayList<String>) {
        /*
        Use the operator at the top of the operator stack to perform the operation on the two numbers at the top of the operator stack, and store the results at the top of the operator stack
        :param operand_stack:ArrayList<Float64>
        :param operator_stack:ArrayList<String>
        :return: the updated operand_stack and operator_stack
        >>> calculator = Calculator()
        >>> calculator.apply_operator(ArrayList<Float64>([1, 2, 3]), ArrayList<String>(['+', '-']))
        ([1, -1], ['-'])
        */
        if (operand_stack.size < 2 || operator_stack.empty()) {
            return (operand_stack, operator_stack)
        }
        let op = operator_stack[operator_stack.size - 1]
        operator_stack.remove(at: operator_stack.size - 1)
        let b = operand_stack[operand_stack.size - 1]
        operand_stack.remove(at: operand_stack.size - 1)
        let a = operand_stack[operand_stack.size - 1]
        operand_stack.remove(at: operand_stack.size - 1)
        let operation = operators[op]
        let result = operation(a, b)
        operand_stack.add(result)
        (operand_stack, operator_stack)
    }

    // Helper function to tokenize expression
    private func tokenize(expression: String): ArrayList<String> {
        var tokens = ArrayList<String>()
        var i = 0
        while (i < expression.length()) {
            let ch = expression[i]
            if (ch == ' ') {
                i = i + 1
                continue
            }
            if (ch >= '0' && ch <= '9' || ch == '.') {
                var j = i
                while (j < expression.length() && (expression[j] >= '0' && expression[j] <= '9' || expression[j] == '.')) {
                    j = j + 1
                }
                tokens.add(expression.substring(i, j))
                i = j
                continue
            }
            if (ch == '+' || ch == '-' || ch == '*' || ch == '/' || ch == '^' || ch == '(' || ch == ')') {
                tokens.add(String([ch]))
                i = i + 1
                continue
            }
            // Invalid character
            tokens.add(String([ch]))
            i = i + 1
        }
        tokens
    }

    // Helper function to check if a token is a number
    private func is_number(token: String): Bool {
        if (token.empty()) {
            return false
        }
        var dot_count = 0
        for (i in 0..token.length()) {
            let ch = token[i]
            if (i == 0 && ch == '-') {
                continue
            }
            if (ch == '.') {
                dot_count = dot_count + 1
                if (dot_count > 1) {
                    return false
                }
                continue
            }
            if (ch < '0' || ch > '9') {
                return false
            }
        }
        true
    }

    // Helper function to parse float
    private func parse_float(s: String): Option<Float64> {
        // Simplified float parsing. In a real implementation, use proper parsing.
        var result: Float64 = 0.0
        var sign = 1.0
        var i = 0
        if (s.empty()) {
            return None<Float64>()
        }
        if (s[0] == '-') {
            sign = -1.0
            i = 1
        }
        var has_decimal = false
        var decimal_place = 1.0
        var integer_part: Float64 = 0.0
        var decimal_part: Float64 = 0.0
        while (i < s.length()) {
            let ch = s[i]
            if (ch == '.') {
                if (has_decimal) {
                    return None<Float64>() // Multiple dots
                }
                has_decimal = true
            } else if (ch >= '0' && ch <= '9') {
                let digit = Float64(ch - '0')
                if (!has_decimal) {
                    integer_part = integer_part * 10.0 + digit
                } else {
                    decimal_part = decimal_part + digit / (10.0 ** decimal_place)
                    decimal_place = decimal_place + 1.0
                }
            } else {
                return None<Float64>() // Invalid character
            }
            i = i + 1
        }
        result = sign * (integer_part + decimal_part)
        Some<Float64>(result)
    }
}

