        if (operand_stack.size < 2 || operator_stack.isEmpty()) {
            return (operand_stack, operator_stack)
        }

        let op = operator_stack.removeLast()
        let b = operand_stack.removeLast()
        let a = operand_stack.removeLast()
        let operation = operators[op]
        let result = operation(a, b)
        operand_stack.add(result)

        (operand_stack, operator_stack)
    }

    // Helper function to tokenize the expression
    private func tokenize(expression: String): ArrayList<String> {
        let tokens = ArrayList<String>()
        var i = 0
        while (i < expression.size) {
            let ch = expression[i]
            if (ch.isWhitespace()) {
                i += 1
                continue
            }

            if (ch.isDigit() || ch == '.') {
                var j = i
                while (j < expression.size && (expression[j].isDigit() || expression[j] == '.')) {
                    j += 1
                }
                tokens.add(expression.substring(i, j))
                i = j
                continue
            }

            if (ch == '+' || ch == '-' || ch == '*' || ch == '/' || ch == '^' || ch == '(' || ch == ')') {
                tokens.add(String([ch]))
                i += 1
                continue
            }

            return ArrayList<String>() // Invalid character
        }
        tokens
    }

    // Check if a token is a number
    private func is_number(token: String): Bool {
        token.toFloat64().isSome()
    }

    private func is_operator(token: String): Bool {
        operators.contains(token)
    }
}

