        operators.add("*", {x: Float64, y: Float64 => x * y})
        operators.add("/", {x: Float64, y: Float64 => x / y})
        operators.add("^", {x: Float64, y: Float64 => x ** y})
    }

    public func calculate(expression: String): Option<Float64> {
        /*
        Calculate the value of a given expression
        :param expression: String, given expression
        :return:If successful, returns the value of the expression; otherwise, returns None
        >>> calculator = Calculator()
        >>> calculator.calculate('1+2-3')
        0.0
        */
        let tokens = tokenize(expression)
        let (postfix, success) = infix_to_postfix(tokens)
        if (!success) {
            return None<Float64>
        }
        return evaluate_postfix(postfix)
    }

    func tokenize(expression: String): ArrayList<String> {
        let tokens = ArrayList<String>()
        var current_number = ""
        for (ch in expression.runes()) {
            let char_str = ch.toString()
            if (char_str == " ") {
                continue
            }
            if (char_str == "+" || char_str == "-" || char_str == "*" || char_str == "/" || char_str == "^" || char_str == "(" || char_str == ")") {
                if (current_number != "") {
                    tokens.add(current_number)
                    current_number = ""
                }
                tokens.add(char_str)
            } else {
                current_number += char_str
            }
        }
        if (current_number != "") {
            tokens.add(current_number)
        }
        return tokens
    }

    public func precedence(op: String): Int64 {
        /*
        Returns the priority of the specified operator, where the higher the priority, the greater the assignment. The priority of '^' is greater than '/' and '*', and the priority of '/' and '*' is greater than '+' and '-'
        :param operator: String, given operator
        :return: Int64, the priority of the given operator, otherwise return 0
        >>> calculator = Calculator()
        >>> calculator.precedence('+')
        1
        >>> calculator.precedence('^')
        3
        */
        match (op) {
            case "+" => 1
            case "-" => 1
            case "*" => 2
            case "/" => 2
            case "^" => 3
            case _ => 0
        }
    }

    public func apply_operator(operand_stack: ArrayList<Float64>, operator_stack: ArrayList<String>): (ArrayList<Float64>, ArrayList<String>) {
        /*
        Use the operator at the top of the operator stack to perform the operation on the two numbers at the top of the operator stack, and store the results at the top of the operator stack
        :param operand_stack:ArrayList<Float64>
        :param operator_stack:ArrayList<String>
        :return: the updated operand_stack and operator_stack
        >>> calculator = Calculator()
        >>> calculator.apply_operator(ArrayList<Float64>([1, 2, 3]), ArrayList<String>(['+', '-']))
        ([1, -1], ['-'])
        */
        if (operator_stack.size == 0 || operand_stack.size < 2) {
            return (operand_stack, operator_stack)
        }
        let op = operator_stack.removeLast()
        let b = operand_stack.removeLast()
        let a = operand_stack.removeLast()
        let operation = operators[op]
        let result = operation(a, b)
        operand_stack.add(result)
        return (operand_stack, operator_stack)
    }

    func infix_to_postfix(tokens: ArrayList<String>): (ArrayList<String>, Bool) {
        let output = ArrayList<String>()
        let operator_stack = ArrayList<String>()
        let operators_set = HashSet<String>(["+", "-", "*", "/", "^"])
        let left_paren = "("
        let right_paren = ")"

        for (token in tokens) {
            if (is_number(token)) {
                output.add(token)
            } else if (token == left_paren) {
                operator_stack.add(token)
            } else if (token == right_paren) {
                var found = false
                while (operator_stack.size > 0) {
                    let op = operator_stack.removeLast()
                    if (op == left_paren) {
                        found = true
                        break
                    }
                    output.add(op)
                }
                if (!found) {
                    return (output, false) // Mismatched parentheses
                }
            } else if (operators_set.contains(token)) {
                while (operator_stack.size > 0 && 
                       operator_stack[operator_stack.size - 1] != left_paren &&
                       precedence(operator_stack[operator_stack.size - 1]) >= precedence(token)) {
                    output.add(operator_stack.removeLast())
                }
                operator_stack.add(token)
            } else {
                return (output, false) // Invalid token
            }
        }

        while (operator_stack.size > 0) {
            let op = operator_stack.removeLast()
            if (op == left_paren || op == right_paren) {
                return (output, false) // Mismatched parentheses
            }
            output.add(op)
        }

        return (output, true)
    }

    func is_number(token: String): Bool {
        // Simple check for number
        if (token.size == 0) {
            return false
        }
        var seen_dot = false
        for (i in 0..token.size) {
            let ch = token.runes().get(i).getOrThrow()
            if (ch.isDigit()) {
                continue
            }
            if (ch == '.' && !seen_dot) {
                seen_dot = true
                continue
            }
            return false
        }
        return true
    }

    func evaluate_postfix(postfix: ArrayList<String>): Option<Float64> {
        let stack = ArrayList<Float64>()
        let operators_set = HashSet<String>(["+", "-", "*", "/", "^"])

        for (token in postfix) {
            if (is_number(token)) {
                let parsed = Float64.parse(token)
                match (parsed) {
                    case Some(val) => stack.add(val)
                    case None => return None<Float64>
                }
            } else if (operators_set.contains(token)) {
                if (stack.size < 2) {
                    return None<Float64>
                }
                let b = stack.removeLast()
                let a = stack.removeLast()
                let operation = operators[token]
                let result = operation(a, b)
                stack.add(result)
            } else {
                return None<Float64>
            }
        }

        if (stack.size != 1) {
            return None<Float64>
        }

        return Some<Float64>(stack[0])
    }
}

