        let op = operator_stack[operator_stack.size - 1]
        operator_stack.remove(at: operator_stack.size - 1)

        let b = operand_stack[operand_stack.size - 1]
        operand_stack.remove(at: operand_stack.size - 1)
        let a = operand_stack[operand_stack.size - 1]
        operand_stack.remove(at: operand_stack.size - 1)

        let operation = operators[op]
        let result = operation(a, b)
        operand_stack.add(result)

        (operand_stack, operator_stack)
    }

    // Helper function to tokenize the input string
    func tokenize(expression: String): ArrayList<String> {
        let tokens = ArrayList<String>()
        var i = 0
        let chars = expression.toRuneArray()

        while (i < chars.size) {
            let ch = chars[i]

            if (ch == r' ') {
                i = i + 1
                continue
            }

            if (ch == r'+' || ch == r'-' || ch == r'*' || ch == r'/' || ch == r'^' || ch == r'(' || ch == r')') {
                tokens.add(String([ch]))
                i = i + 1
                continue
            }

            // Number parsing
            var j = i
            while (j < chars.size && (chars[j].isDigit() || chars[j] == r'.')) {
                j = j + 1
            }
            let num_str = String(chars[i..j])
            tokens.add(num_str)
            i = j
        }

        tokens
    }

    // Helper function to check if a token is a number
    func is_number(token: String): Bool {
        var has_dot = false
        let runes = token.toRuneArray()
        for (i in 0..runes.size) {
            let ch = runes[i]
            if (ch == r'.') {
                if (has_dot) {
                    return false
                }
                has_dot = true
            } else if (!ch.isDigit()) {
                return false
            }
        }
        runes.size > 0 && runes[0].isDigit()
    }
}

