        Calculate the value of a given expression
        :param expression: String, given expression
        :return:If successful, returns the value of the expression; otherwise, returns None
        >>> calculator = Calculator()
        >>> calculator.calculate('1+2-3')
        0.0
        */
        let tokens = tokenize(expression)
        let operand_stack = ArrayList<Float64>()
        let operator_stack = ArrayList<String>()

        for (token in tokens) {
            if (is_number(token)) {
                let num = Float64.parse(token)
                if (num is Some<Float64>) {
                    operand_stack.add(num.getOrThrow())
                } else {
                    return None<Float64>
                }
            } else if (token == "(") {
                operator_stack.add(token)
            } else if (token == ")") {
                while (operator_stack.size > 0 && operator_stack[operator_stack.size - 1] != "(") {
                    let result = apply_operator(operand_stack, operator_stack)
                    operand_stack = result[0]
                    operator_stack = result[1]
                }
                if (operator_stack.size > 0) {
                    operator_stack.remove(at: operator_stack.size - 1) // remove "("
                } else {
                    return None<Float64> //Mismatched parentheses
                }
            } else if (operators.contains(token)) {
                while (operator_stack.size > 0 && 
                       operator_stack[operator_stack.size - 1] != "(" &&
                       precedence(operator_stack[operator_stack.size - 1]) >= precedence(token)) {
                    let result = apply_operator(operand_stack, operator_stack)
                    operand_stack = result[0]
                    operator_stack = result[1]
                }
                operator_stack.add(token)
            } else {
                return None<Float64> //Invalid token
            }
        }

        while (operator_stack.size > 0) {
