        }

        operand_stack.remove(at: operand_stack.size - 1)
        operand_stack.remove(at: operand_stack.size - 1)
        operator_stack.remove(at: operator_stack.size - 1)

        operand_stack.add(result.getOrThrow())
        (operand_stack, operator_stack)
    }

    private func operation(op: String, x: Float64, y: Float64): Option<Float64> {
        let func_opt = operators[op]
        if (func_opt == None<(Float64, Float64) -> Float64>) {
            return None<Float64>
        }
        let f = func_opt.getOrThrow()
        if (op == "/" && y == 0.0) {
            return None<Float64> // Division by zero
        }
        Some<Float64>(f(x, y))
    }

    private func tokenize(expression: String): ArrayList<String> {
