                i = i + 1
                continue
            }
            // Number
            var num_str = ""
            while (i < expression.size && (is_digit(expression[i]) || expression[i] == '.')) {
                num_str = num_str + expression[i].toString()
                i = i + 1
            }
            if (num_str != "") {
                tokens.add(num_str)
            }
        }
        tokens
    }

    private func is_number(s: String): Bool {
        var dot_count = 0
        for (i in 0..s.size) {
            let ch = s[i]
            if (ch == '.') {
                dot_count = dot_count + 1
                if (dot_count > 1) {
                    return false
                }
            } else if (!is_digit(ch)) {
                return false
            }
        }
        true
    }

    private func parse_number(s: String): Option<Float64> {
        if (!is_number(s)) {
            return None<Float64>
        }
        let parsed = Float64.fromString(s)
        if (parsed == None<Float64>) {
            return None<Float64>
        }
        Some<Float64>(parsed.getOrThrow())
    }

    private func is_digit(ch: Rune): Bool {
        ch >= r'0' && ch <= r'9'
    }
