        Some<Float64>(operand_stack[0])
    }

    public func precedence(op: String): Int64 {
        /*
        Returns the priority of the specified operator, where the higher the priority, the greater the assignment. The priority of '^' is greater than '/' and '*', and the priority of '/' and '*' is greater than '+' and '-'
        :param operator: String, given operator
        :return: Int64, the priority of the given operator, otherwise return 0
        >>> calculator = Calculator()
        >>> calculator.precedence('+')
        1
        >>> calculator.precedence('^')
        3
        */
        match (op) {
            case "+" => 1
            case "-" => 1
            case "*" => 2
            case "/" => 2
            case "^" => 3
            case _ => 0
        }
    }

    public func apply_operator(operand_stack: ArrayList<Float64>, operator_stack: ArrayList<String>): (ArrayList<Float64>, ArrayList<String>) {
        /*
        Use the operator at the top of the operator stack to perform the operation on the two numbers at the top of the operator stack, and store the results at the top of the operator stack
        :param operand_stack:ArrayList<Float64>
        :param operator_stack:ArrayList<String>
        :return: the updated operand_stack and operator_stack
        >>> calculator = Calculator()
        >>> calculator.apply_operator(ArrayList<Float64>([1, 2, 3]), ArrayList<String>(['+', '-']))
        ([1, -1], ['-'])
        */
        if (operand_stack.size < 2 || operator_stack.size < 1) {
            return (operand_stack, operator_stack)
        }

        let op = operator_stack[operator_stack.size - 1]
        operator_stack.remove(at: operator_stack.size - 1)

        let b = operand_stack[operand_stack.size - 1]
        operand_stack.remove(at: operand_stack.size - 1)
        let a = operand_stack[operand_stack.size - 1]
        operand_stack.remove(at: operand_stack.size - 1)

        let operation = operators[op]
        let result = operation(a, b)
        operand_stack.add(result)

        (operand_stack, operator_stack)
    }
}

import std.collection.HashMap
import std.collection.ArrayList
import std.collection.HashSet
import std.convert.Parsable

class Calculator {

    /*
    This is a class for a calculator, capable of performing basic arithmetic calculations on numerical expressions using the operators +, -, *, /, and ^ (exponentiation).
    */

    let operators: HashMap<String, (Float64, Float64) -> Float64>
    let operator_set: HashSet<String>

    public init() {
        /*
        Initialize the operations performed by the five operators'+','-','*','/','^'
        */
        this.operators = HashMap<String, (Float64, Float64) -> Float64>()
        this.operator_set = HashSet<String>()
        operators.add("+", {x: Float64, y: Float64 => x + y})
        operators.add("-", {x: Float64, y: Float64 => x - y})
        operators.add("*", {x: Float64, y: Float64 => x * y})
        operators.add("/", {x: Float64, y: Float64 => x / y})
        operators.add("^", {x: Float64, y: Float64 => x ** y})

        operator_set.add("+")
        operator_set.add("-")
        operator_set.add("*")
        operator_set.add("/")
        operator_set.add("^")
    }

    public func calculate(expression: String): Option<Float64> {
        /*
        Calculate the value of a given expression
        :param expression: String, given expression
        :return:If successful, returns the value of the expression; otherwise, returns None
        >>> calculator = Calculator()
        >>> calculator.calculate('1+2-3')
        0.0
        */
        let operand_stack = ArrayList<Float64>()
        let operator_stack = ArrayList<String>()
        var i = 0

        while (i < expression.size) {
            let char = expression[i]

            if (char == ' ') {
                i += 1
                continue
            }

            if ((char >= '0' && char <= '9') || char == '.') {
                // Parse number
                let start = i
                while (i < expression.size && ((expression[i] >= '0' && expression[i] <= '9') || expression[i] == '.')) {
                    i += 1
                }
                let num_str = expression[start..i]
                let num = Float64.parsed(num_str) ?? return None<Float64>()
                operand_stack.add(num)
                continue
            }

            if (operator_set.contains(String(char))) {
                let op = String(char)
                while (operator_stack.size > 0 && precedence(operator_stack[operator_stack.size - 1]) >= precedence(op)) {
                    if (!apply_operator_inplace(operand_stack, operator_stack)) {
                        return None<Float64>()
                    }
                }
                operator_stack.add(op)
                i += 1
                continue
            }

            if (char == '(') {
                operator_stack.add(String(char))
                i += 1
                continue
            }

            if (char == ')') {
                while (operator_stack.size > 0 && operator_stack[operator_stack.size - 1] != "(") {
                    if (!apply_operator_inplace(operand_stack, operator_stack)) {
                        return None<Float64>()
                    }
                }
                if (operator_stack.size == 0) {
                    return None<Float64>() // Mismatched parentheses
                }
                operator_stack.remove(at: operator_stack.size - 1) // Remove '('
                i += 1
                continue
            }

            // Invalid character
            return None<Float64>()
        }

        while (operator_stack.size > 0) {
            if (operator_stack[operator_stack.size - 1] == "(" || operator_stack[operator_stack.size - 1] == ")") {
                return None<Float64>() // Mismatched parentheses
            }
            if (!apply_operator_inplace(operand_stack, operator_stack)) {
                return None<Float64>()
            }
        }

        if (operand_stack.size != 1) {
            return None<Float64>()
        }

        Some<Float64>(operand_stack[0])
    }

    // Helper function to apply operator
    private func apply_operator_inplace(operand_stack: ArrayList<Float64>, operator_stack: ArrayList<String>): Bool {
        if (operator_stack.size == 0 || operand_stack.size < 2) {
            return false
        }
        let op = operator_stack.remove(at: operator_stack.size - 1)
        let b = operand_stack.remove(at: operand_stack.size - 1)
        let a = operand_stack.remove(at: operand_stack.size - 1)
        let func_op = operators[op] ?? return false
        operand_stack.add(func_op(a, b))
        return true
    }

    public func precedence(op: String): Int64 {
        /*
        Returns the priority of the specified operator, where the higher the priority, the greater the assignment. The priority of '^' is greater than '/' and '*', and the priority of '/' and '*' is greater than '+' and '-'
        :param operator: String, given operator
        :return: Int64, the priority of the given operator, otherwise return 0
        >>> calculator = Calculator()
        >>> calculator.precedence('+')
        1
        >>> calculator.precedence('^')
        3
        */
        match (op) {
            case "+" => 1
            case "-" => 1
            case "*" => 2
            case "/" => 2
            case "^" => 3
            case _ => 0
        }
    }

    public func apply_operator(operand_stack: ArrayList<Float64>, operator_stack: ArrayList<String>): (ArrayList<Float64>, ArrayList<String>) {
        /*
        Use the operator at the top of the operator stack to perform the operation on the two numbers at the top of the operator stack, and store the results at the top of the operator stack
        :param operand_stack:ArrayList<Float64>
        :param operator_stack:ArrayList<String>
        :return: the updated operand_stack and operator_stack
        >>> calculator = Calculator()
        >>> calculator.apply_operator(ArrayList<Float64>([1, 2, 3]), ArrayList<String>(['+', '-']))
        ([1, -1], ['-'])
        */
        var operands = operand_stack
        var operators = operator_stack

        if (operators.size > 0 && operands.size >= 2) {
            let op = operators[operators.size - 1]
            operators.remove(at: operators.size - 1)

            let b = operands[operands.size - 1]
            operands.remove(at: operands.size - 1)
            let a = operands[operands.size - 1]
            operands.remove(at: operands.size - 1)

            let func_op = this.operators[op] ?? { _: Float64, _: Float64 => 0.0 }
            let result = func_op(a, b)
            operands.add(result)
        }

        (operands, operators)
    }
}

