        let file_content = read_file(file_name)
        let lines = file_content.split('\n')
        let title = ArrayList<String>()
        let data = ArrayList<ArrayList<String>>()

        if (lines.size == 0) {
            return (title, data)
        }

        // Process header
        let header_line = lines[0]
        let header_fields = header_line.split(',')
        for (field in header_fields) {
            title.add(field.trim())
        }

        // Process data rows
        for (i in 1..lines.size) {
            if (lines[i].isEmpty()) {
                continue
            }
            let row_fields = lines[i].split(',')
            let row = ArrayList<String>()
            for (field in row_fields) {
                row.add(field.trim())
            }
            data.add(row)
        }

        return (title, data)
    }

