class CSVProcessor {

    /*
    This is a class for processing CSV files, including reading and writing CSV data, as well as processing specific operations and saving as a new CSV file.
    */

    public init() {}

    public func read_csv(file_name: String): (ArrayList<String>, ArrayList<ArrayList<String>>) {
        let lines = read_lines(file_name)
        if (lines.size == 0) {
            return (ArrayList<String>(), ArrayList<ArrayList<String>>())
        }

        let title = parse_csv_line(lines[0])
        let data = ArrayList<ArrayList<String>>()

        for (i in 1..lines.size) {
            data.add(parse_csv_line(lines[i]))
        }

        return (title, data)
    }

    public func write_csv(data: ArrayList<ArrayList<String>>, file_name: String): Int64 {
        let file = open(file_name, mode: "w")
        if (file.isNone()) {
            return 0
        }
        let f = file.getOrThrow()

        for (row in data) {
            let line = join_csv_row(row)
            f.write(line + "\n")
        }

        f.close()
        return 1
    }

    public func process_csv_data(N: Int64, save_file_name: String): Int64 {
        let (title, data) = read_csv(save_file_name)

        if (title.size <= N || N < 0) {
            return 0
        }

        let new_data = ArrayList<ArrayList<String>>()
        for (row in data) {
            if (row.size > N) {
                let processed_row = ArrayList<String>()
                processed_row.add(row[N].toUpper())
                new_data.add(processed_row)
            }
        }

        let base_name = get_base_name(save_file_name)
        let new_file_name = base_name + "_process.csv"
        let all_data = ArrayList<ArrayList<String>>()
        all_data.add(title)
        for (row in new_data) {
            all_data.add(row)
        }

        return write_csv(all_data, new_file_name)
    }

    private func parse_csv_line(line: String): ArrayList<String> {
        let result = ArrayList<String>()
        let fields = line.split(',')
        for (field in fields) {
            // Remove quotes if present and trim whitespace
            let trimmed = field.trim()
            if (trimmed.size >= 2 && trimmed[0] == '"' && trimmed[trimmed.size - 1] == '"') {
                result.add(trimmed.slice(1, trimmed.size - 1))
            } else {
                result.add(trimmed)
            }
        }
        return result
    }

    private func join_csv_row(row: ArrayList<String>): String {
        let parts = ArrayList<String>()
        for (cell in row) {
            parts.add("\"" + cell + "\"")
        }
        return parts.join(",")
    }

    private func get_base_name(file_name: String): String {
        let parts = file_name.split('.')
        if (parts.size <= 1) {
            return file_name
        }
        let base_parts = ArrayList<String>()
        for (i in 0..parts.size - 1) {
            base_parts.add(parts[i])
        }
        return base_parts.join(".")
    }
}

