        let result = ArrayList<String>()
        let fields = line.split(',')
        for (field in fields) {
            let trimmed = field.trim()
            if (trimmed.startsWith("\"") && trimmed.endsWith("\"")) {
                result.add(trimmed.substring(1, trimmed.size - 1))
            } else {
                result.add(trimmed)
            }
        }
        return result
    }

    private func join_row(row: ArrayList<String>): String {
        let escaped_row = ArrayList<String>()
        for (field in row) {
            if (field.contains(",") || field.contains("\"") || field.contains("\n")) {
                let escaped = field.replace("\"", "\"\"")
                escaped_row.add("\"${escaped}\"")
            } else {
                escaped_row.add(field)
            }
        }
        return escaped_row.join(",")
    }
}

