import std.collection.*
import std.fs.*
import std.io.*
import std.unicode.UnicodeStringExtension

class CSVProcessor {

    public init() {}

    public func read_csv(file_name: String): (ArrayList<String>, ArrayList<ArrayList<String>>) {
        let file = open_readable_file(file_name).getOrThrow()
        let lines = file.read_all_lines().getOrThrow()
        file.close()

        let title = ArrayList<String>()
        let data = ArrayList<ArrayList<String>>()

        if (lines.size == 0) {
            return (title, data)
        }

        let title_line = lines[0]
        let title_parts = parse_line(title_line)
        for (part in title_parts) {
            title.add(part)
        }

        for (i in 1..lines.size) {
            let line = lines[i]
            let parts = parse_line(line)
            let row = ArrayList<String>()
            for (part in parts) {
                row.add(part)
            }
            data.add(row)
        }

        return (title, data)
    }

    public func write_csv(data: ArrayList<ArrayList<String>>, file_name: String): Int64 {
        let file = open_writable_file(file_name)
        if (file is None) {
            return 0
        }
        let f = file.getOrThrow()

        for (row in data) {
            let line = format_line(row)
            f.write_line(line)
        }

        f.close()
        return 1
    }

    public func process_csv_data(N: Int64, save_file_name: String): Int64 {
        let result = read_csv(save_file_name)
        let titles = result[0]
        let data_rows = result[1]

        if (titles.size <= N || N < 0) {
            return 0
        }

        let new_data = ArrayList<ArrayList<String>>()
        new_data.add(titles)

        for (row in data_rows) {
            if (row.size <= N) {
                continue
            }
            let processed_row = ArrayList<String>()
            processed_row.add(row[N].to_uppercase())
            new_data.add(processed_row)
        }

        let base_name = if (save_file_name.ends_with(".csv")) {
            save_file_name.substring(0, save_file_name.size - 4)
        } else {
            save_file_name
        }
        let new_file_name = "${base_name}_process.csv"

        return write_csv(new_data, new_file_name)
    }

    // Helper: parse a CSV line into fields (very basic implementation without full RFC 4180 support)
    private func parse_line(line: String): ArrayList<String> {
        let fields = ArrayList<String>()
        let runes = line.to_rune_array()
        var i = 0
        var in_quotes = false
        var current_field = ""

        while (i < runes.size) {
            let r = runes[i]

            if (r == r'"') {
                if (in_quotes && i + 1 < runes.size && runes[i+1] == r'"') {
                    // Escaped quote
                    current_field = current_field + "\""
                    i = i + 2
                    continue
                } else {
                    in_quotes = !in_quotes
                }
            } else if (r == r',' && !in_quotes) {
                fields.add(current_field)
                current_field = ""
            } else {
                let char_str = String([r])
                current_field = current_field + char_str
            }
            i = i + 1
        }
        fields.add(current_field) // Add last field
        return fields
    }

    // Helper: format a row of fields into a CSV line
    private func format_line(row: ArrayList<String>): String {
        let formatted_fields = ArrayList<String>()
        for (field in row) {
            // If field contains comma, quote or newline, wrap in quotes and escape internal quotes
            let need_quotes = field.contains(",") || field.contains("\"") || field.contains("\n")
            var escaped_field = field

            if (need_quotes) {
                escaped_field = field.replace("\"", "\"\"")
                escaped_field = "\"${escaped_field}\""
            }

            formatted_fields.add(escaped_field)
        }

        var result = ""
        for (i in 0..formatted_fields.size) {
            result = result + formatted_fields[i]
            if (i != formatted_fields.size - 1) {
                result = result + ","
            }
        }
        return result
    }
}

