class CSVProcessor {

    /*
    This is a class for processing CSV files, including reading and writing CSV data, as well as processing specific operations and saving as a new CSV file.
    */

    public init() {}

    public func read_csv(file_name: String): (ArrayList<String>, ArrayList<ArrayList<String>>) {
        let file = open(file_name, mode: FileMode.READ)
        if (file.isNone()) {
            return (ArrayList<String>(), ArrayList<ArrayList<String>>())
        }
        let f = file.getOrThrow()
        let lines = f.readAllLines().getOrThrow()
        f.close()

        if (lines.size == 0) {
            return (ArrayList<String>(), ArrayList<ArrayList<String>>())
        }

        let title = parse_csv_line(lines[0])
        let data = ArrayList<ArrayList<String>>()

        for (i in 1..lines.size) {
            let line = lines[i]
            let row = parse_csv_line(line)
            data.add(row)
        }

        return (title, data)
    }

    public func write_csv(data: ArrayList<ArrayList<String>>, file_name: String): Int64 {
        let file = open(file_name, mode: FileMode.WRITE)
        if (file.isNone()) {
            return 0
        }
        let f = file.getOrThrow()

        for (row in data) {
            let line = join_csv_row(row)
            f.writeLine(line)
        }
        f.close()
        return 1
    }

    public func process_csv_data(N: Int64, save_file_name: String): Int64 {
        let result = read_csv(save_file_name)
        let title = result[0]
        let data = result[1]

        if (title.size <= N || N < 0) {
            return 0
        }

        let new_data = ArrayList<ArrayList<String>>()
        new_data.add(title)

        for (row in data) {
            if (row.size > N) {
                let new_row = ArrayList<String>()
                let processed = row[N].toUpper()
                new_row.add(processed)
                new_data.add(new_row)
            }
        }

        let save_name = "${save_file_name}_process"
        return write_csv(new_data, save_name)
    }

    // Helper to parse a CSV line, handling quoted fields
    private func parse_csv_line(line: String): ArrayList<String> {
        let result = ArrayList<String>()
        let chars = line.toRuneArray()
        var i = 0
        var field_start = 0
        var in_quotes = false
        let comma: Rune = r','

        while (i < chars.size) {
            let ch = chars[i]
            if (ch == r'"') {
                in_quotes = !in_quotes
            } else if (ch == comma && !in_quotes) {
                let field = String(chars[field_start..i])
                result.add(trim_quotes(field))
                field_start = i + 1
            }
            i += 1
        }

        let last_field = String(chars[field_start..chars.size])
        result.add(trim_quotes(last_field))
        return result
    }

    // Helper to trim surrounding quotes from a field
    private func trim_quotes(field: String): String {
        let runes = field.toRuneArray()
        if (runes.size >= 2 && runes[0] == r'"' && runes[runes.size - 1] == r'"') {
            return String(runes[1..runes.size - 1])
        }
        return field
    }

    // Helper to join a row into a CSV line
    private func join_csv_row(row: ArrayList<String>): String {
        let parts = ArrayList<String>()
        for (field in row) {
            parts.add("\"${field}\"")
        }
        return parts.join(",")
    }
}

import std.collection.ArrayList
