class CSVProcessor {

    public init() {}

    public func read_csv(file_name: String): (ArrayList<String>, ArrayList<ArrayList<String>>) {
        let file = open(file_name, mode: "r") ?? panic("Cannot open file: ${file_name}")
        let lines = file.readAllLines()
        file.close()

        if (lines.size == 0) {
            return (ArrayList<String>(), ArrayList<ArrayList<String>>())
        }

        let header_line = lines[0]
        let title = parse_csv_line(header_line)

        let data = ArrayList<ArrayList<String>>()
        for (i in 1..lines.size) {
            let line = lines[i]
            let row = parse_csv_line(line)
            data.add(row)
        }

        return (title, data)
    }

    public func write_csv(data: ArrayList<ArrayList<String>>, file_name: String): Int64 {
        let file = open(file_name, mode: "w") ?? return 0
        for (row in data) {
            let line = join_csv_row(row)
            file.writeLine(line)
        }
        file.close()
        return 1
    }

    public func process_csv_data(N: Int64, save_file_name: String): Int64 {
        let (title, data) = read_csv(save_file_name)

        if (title.size <= N || N < 0) {
            return 0
        }

        let new_data = ArrayList<ArrayList<String>>()
        for (row in data) {
            if (row.size > N) {
                let cell = row[N].toUpper()
                new_data.add(ArrayList<String>([cell]))
            } else {
                new_data.add(ArrayList<String>())
            }
        }

        let base_name = save_file_name.substring(0, save_file_name.lastIndexOf(".") ?? save_file_name.size)
        let new_file_name = "${base_name}_process.csv"

        let new_full_data = ArrayList<ArrayList<String>>()
        new_full_data.add(title)
        for (row in new_data) {
            new_full_data.add(row)
        }

        return write_csv(new_full_data, new_file_name)
    }

    // Helper function to parse a CSV line into fields
    private func parse_csv_line(line: String): ArrayList<String> {
        let fields = ArrayList<String>()
        var current = ""
        var in_quotes = false
        var i = 0

        while (i < line.size) {
            let ch = line[i]
            if (ch == '"' && (i == 0 || line[i - 1] != '\\')) {
                in_quotes = !in_quotes
            } else if (ch == ',' && !in_quotes) {
                fields.add(current)
                current = ""
            } else {
                current = current + ch
            }
            i = i + 1
        }
        fields.add(current)
        return fields
    }

    // Helper function to join a row of strings into a CSV line
    private func join_csv_row(row: ArrayList<String>): String {
        let processed = ArrayList<String>()
        for (field in row) {
            // Escape quotes and wrap in quotes if needed
            let escaped = field.replace("\"", "\"\"")
            if (escaped.contains(",") || escaped.contains("\"") || escaped.contains("\n")) {
                processed.add("\"${escaped}\"")
            } else {
                processed.add(escaped)
            }
        }

        var result = ""
        for (i in 0..processed.size) {
            if (i > 0) {
                result = result + ","
            }
            result = result + processed[i]
        }
        return result
    }
}

