        >>> d.caesar_decipher('ifmmp', 1)
        'hello'

        */
        var result = ""
        for (char in ciphertext.runes()) {
            if (char >= r'A' && char <= r'Z') {
                let base = Int64(char) - Int64(r'A')
                let shifted = (base - shift) % 26
                let normalized = if (shifted < 0) { shifted + 26 } else { shifted }
                result = result + Rune(UInt32(normalized + Int64(r'A')))
            } else if (char >= r'a' && char <= r'z') {
                let base = Int64(char) - Int64(r'a')
                let shifted = (base - shift) % 26
                let normalized = if (shifted < 0) { shifted + 26 } else { shifted }
                result = result + Rune(UInt32(normalized + Int64(r'a')))
            } else {
                result = result + char
            }
        }
        return result
    }

