        // Read the result in zig-zag manner
        var result = ""
        row = 0
        down = true
        for (i in 0..n) {
            let char = rail_matrix[row][i].getOrThrow()
            result = result + char
            if (row == 0) {
                down = true
            }
            if (row == Int64(rails) - 1) {
                down = false
            }
            row = if (down) { row + 1 } else { row - 1 }
        }

