        if (n == 0 || rails <= 1) {
            return encrypted_text
        }

        // Create an array of ArrayList to store characters for each rail
        let railArray = ArrayList<ArrayList<Rune>>()
        for (i in 0..(rails as IntNative)) {
            railArray.add(ArrayList<Rune>())
        }

        // Mark the pattern of rails
        let railPattern = ArrayList<Int64>()
        var currentRail = 0 as Int64
        var direction = 1 as Int64

        for (i in 0..n) {
            railPattern.add(currentRail)
            if (currentRail == 0) {
                direction = 1
            } else if (currentRail == rails - 1) {
                direction = -1
            }
            currentRail = currentRail + direction
        }

        // Count characters per rail
        let railLengths = ArrayList<Int64>()
        for (i in 0..(rails as IntNative)) {
            railLengths.add(0)
        }

        for (railIndex in railPattern) {
            railLengths[railIndex as IntNative] = railLengths[railIndex as IntNative] + 1
        }

        // Split encrypted_text into rails
        var index = 0 as IntNative
        for (i in 0..(rails as IntNative)) {
            let length = railLengths[i] as IntNative
            for (j in 0..length) {
                railArray[i].add(encrypted_text.runes().nth(index) ?? r' ')
                index = index + 1
            }
        }

        // Read characters in the order of railPattern to reconstruct the plaintext
        var resultRunes = ArrayList<Rune>()
        let railPointers = ArrayList<Int64>()
        for (i in 0..(rails as IntNative)) {
            railPointers.add(0)
        }

        for (railIndex in railPattern) {
            let ptr = railPointers[railIndex as IntNative] as IntNative
            resultRunes.add(railArray[railIndex as IntNative][ptr])
            railPointers[railIndex as IntNative] = railPointers[railIndex as IntNative] + 1
        }

        var resultStr = ""
        for (r in resultRunes) {
            resultStr = resultStr + r
        }

        return resultStr
    }
