            }

            if (visited.contains(current_state)) {
                continue
            }

            visited.add(current_state)
            let possible_moves = get_possible_moves(current_state)

            for (move_dir in possible_moves) {
                let new_state = move(current_state, move_dir)
                if (!visited.contains(new_state)) {
                    let new_path = ArrayList<String>(path)
                    new_path.add(move_dir)
                    queue.add((new_state, new_path))
                }
            }
        }

        return ArrayList<String>() // Return empty path if no solution found
    }
