        */
        let (x, y) = find_blank(state)
        let new_state = ArrayList<ArrayList<Int64>>()
        for (i in 0..3) {
            new_state.add(ArrayList<Int64>(state[i]))
        }

        if (direction == "up" && x > 0) {
            new_state[x][y] = new_state[x - 1][y]
            new_state[x - 1][y] = 0
        } else if (direction == "down" && x < 2) {
            new_state[x][y] = new_state[x + 1][y]
            new_state[x + 1][y] = 0
        } else if (direction == "left" && y > 0) {
            new_state[x][y] = new_state[x][y - 1]
            new_state[x][y - 1] = 0
        } else if (direction == "right" && y < 2) {
            new_state[x][y] = new_state[x][y + 1]
            new_state[x][y + 1] = 0
        }

        return new_state
    }

    public func get_possible_moves(state: ArrayList<ArrayList<Int64>>): ArrayList<String> {
        /*
        According the current state, find all the possible moving directions. Only has 4 direction 'up', 'down', 'left', 'right'.
        :param state: a 3*3 size list of Integer, stores the current state.
