        /*
        Use BFS algorithm to find the path solution which makes the initial state to the goal method.
        Maintain a list as a queue, named as open_list, append the initial state.
        Always visit and pop the 0 index element, invoke get_possible_moves method find all the possible directions.
        Traversal the possible_moves list and invoke move method to get several new states.Then append them.
        redo the above steps until the open_list is empty or the state has changed to the goal state.
        :return path: list of String, the solution to the goal state.
        >>> eightPuzzle = EightPuzzle(ArrayList<ArrayList<Int64>>([ArrayList<Int64>([1, 2, 3]), ArrayList<Int64>([4, 5, 6]), ArrayList<Int64>([7, 0, 8])]))
        >>> eightPuzzle.solve()
        ['right']
        */
        let queue = ArrayList<(ArrayList<ArrayList<Int64>>, ArrayList<String>)>()
        let visited = HashSet<String>()

        queue.add((this.initial_state, ArrayList<String>()))
        visited.add(state_to_string(this.initial_state))

        while (queue.size > 0) {
            let (current_state, path) = queue.remove(at: 0)

            if (current_state == this.goal_state) {
                return path
            }

            let moves = get_possible_moves(current_state)
            for (move in moves) {
                let new_state = this.move(current_state, move)
                let state_str = state_to_string(new_state)

                if (!visited.contains(state_str)) {
                    visited.add(state_str)
                    let new_path = ArrayList<String>(path)
                    new_path.add(move)
                    queue.add((new_state, new_path))
                }
            }
        }

        return ArrayList<String>()  // Return empty list if no solution found
    }

    // Helper function to convert state to string for hashing
    private func state_to_string(state: ArrayList<ArrayList<Int64>>): String {
        let result = ArrayList<String>()
        for (row in state) {
            for (item in row) {
                result.add(item.toString())
            }
        }
        return "[" + result.join(",") + "]"
    }
