    public func caesar_cipher(plaintext: String, shift: Int64): String {
        /*
        Encrypts the plaintext using the Caesar cipher.
        :param plaintext: The plaintext to encrypt, String.
        :param shift: The number of characters to shift each character in the plaintext, Int64.
        :return: The ciphertext, String.
        >>> e = EncryptionUtils("key")
        >>> e.caesar_cipher("abc", 1)
        'bcd'

        */
        let runes = plaintext.toRuneArray()
        let mut result = ArrayList<Rune>()
        for (r in runes) {
            let char_code = r.toInt()
            let shifted = ((char_code - 97 + shift) % 26 + 26) % 26 + 97
            result.add(Rune.fromInt(shifted))
        }
        return String.fromRunes(result)
    }

    public func vigenere_cipher(plain_text: String): String {
        /*
        Encrypts the plaintext using the Vigenere cipher.
        :param plaintext: The plaintext to encrypt, String.
        :return: The ciphertext, String.
        >>> e = EncryptionUtils("key")
        >>> e.vigenere_cipher("abc")
        'kfa'

        */
        let text_runes = plain_text.toRuneArray()
        let key_runes = this.key.toRuneArray()
        let mut result = ArrayList<Rune>()
        for (i in 0..text_runes.size) {
            let text_char = text_runes[i]
            let key_char = key_runes[i % key_runes.size]
            let text_pos = text_char.toInt() - 97
            let key_pos = key_char.toInt() - 97
            let encrypted_char = (text_pos + key_pos) % 26 + 97
            result.add(Rune.fromInt(encrypted_char))
        }
        return String.fromRunes(result)
    }

    public func rail_fence_cipher(plain_text: String, rails: Int64): String {
        /*
        Encrypts the plaintext using the Rail Fence cipher.
        :param plaintext: The plaintext to encrypt, String.
        :param rails: The number of rails to use, Int64.
        :return: The ciphertext, String.
        >>> e = EncryptionUtils("key")
        >>> e.rail_fence_cipher("abc", 2)
        'acb'

        */
        if (rails <= 1) {
            return plain_text
        }

        let runes = plain_text.toRuneArray()
        let mut rails_array = ArrayList<ArrayList<Rune>>()
        for (_ in 0..rails) {
            rails_array.add(ArrayList<Rune>())
        }

        var current_rail = 0
        var step = 1

        for (r in runes) {
            rails_array[current_rail].add(r)

            if (current_rail == 0) {
                step = 1
            } else if (current_rail == rails - 1) {
                step = -1
            }

            current_rail += step
        }

        let mut result = ArrayList<Rune>()
        for (rail in rails_array) {
            for (r in rail) {
                result.add(r)
            }
        }

        return String.fromRunes(result)
    }
}

