        */
        let priority_map = HashMap<String, Int64>([("+", 1), ("-", 1), ("*", 2), ("/", 2), ("%", 2)])
        let cur_priority = priority_map[cur] ?? 0
        let peek_priority = priority_map[peek] ?? 0
        return cur_priority <= peek_priority
    }

    public static func _calculate(first_value: Decimal, second_value: Decimal, current_op: String): Decimal {
