class Hotel {
    let name: String
    let available_rooms: HashMap<String, Int64>
    var booked_rooms: HashMap<String, HashMap<String, Int64>>

    public init(name: String, rooms: HashMap<String, Int64>) {
        this.name = name
        this.available_rooms = HashMap<String, Int64>(rooms)
        this.booked_rooms = HashMap<String, HashMap<String, Int64>>()
    }

    public func book_room(room_type: String, room_number: Int64, name: String): String {
        let available = this.available_rooms.get(room_type)
        if (available == None<Int64>) {
            return "false"
        }

        let available_count = available.getOrThrow()
        if (room_number <= available_count) {
            // Update available rooms
            this.available_rooms.add(room_type, available_count - room_number)

            // Update booked rooms
            let room_type_bookings = this.booked_rooms.get(room_type)
            if (room_type_bookings == None<HashMap<String, Int64>>) {
                let new_booking = HashMap<String, Int64>()
                new_booking.add(name, room_number)
                this.booked_rooms.add(room_type, new_booking)
            } else {
                let bookings = room_type_bookings.getOrThrow()
                let existing_booking = bookings.get(name)
                if (existing_booking == None<Int64>) {
                    bookings.add(name, room_number)
                } else {
                    bookings.add(name, existing_booking.getOrThrow() + room_number)
                }
            }

            return "Success!"
        } else if (available_count > 0) {
            return available_count.toString()
        } else {
            return "false"
        }
    }

    public func check_in(room_type: String, room_number: Int64, name: String): Bool {
        let room_type_bookings = this.booked_rooms.get(room_type)
        if (room_type_bookings == None<HashMap<String, Int64>>) {
            return false
        }

        let bookings = room_type_bookings.getOrThrow()
        let person_booking = bookings.get(name)
        if (person_booking == None<Int64>) {
            return false
        }

        let booked_count = person_booking.getOrThrow()
        if (room_number > booked_count) {
            return false
        }

        if (room_number == booked_count) {
            bookings.remove(name)
        } else {
            bookings.add(name, booked_count - room_number)
        }

        return true
    }

    public func check_out(room_type: String, room_number: Int64): Unit {
        let available = this.available_rooms.get(room_type)
        if (available == None<Int64>) {
            this.available_rooms.add(room_type, room_number)
        } else {
            let current_count = available.getOrThrow()
            this.available_rooms.add(room_type, current_count + room_number)
        }
    }

    public func get_available_rooms(room_type: String): Int64 {
        let available = this.available_rooms.get(room_type)
        if (available == None<Int64>) {
            return 0
        }
        return available.getOrThrow()
    }
}

