        >>> hotel.book_room('triple', 1, 'guest 1')
        'false'
        */
        let maybe_available = this.available_rooms.get(room_type)
        if (maybe_available is None<Int64>) {
            return "false"
        }
        let available = maybe_available.getOrThrow()

        if (room_number <= 0) {
            return "false"
        }

        if (room_number > available) {
            if (available == 0) {
                return "false"
            } else {
                return available.toString()
            }
        } else {
            // Perform booking
            this.available_rooms.add(room_type, available - room_number)

            let inner_map = this.booked_rooms.get(room_type) ?? HashMap<String, Int64>()
            let current_booked = inner_map.get(name) ?? 0
            inner_map.add(name, current_booked + room_number)
            this.booked_rooms.add(room_type, inner_map)

