            let binStr = this.int_to_binary(num)
            binaries.add(binStr)
        }
        return binaries.join(r'.')
    }

    private func int_to_binary(num: Int64): String {
        var n = num
        var binary = ArrayList<Rune>()
        // Generate 8-bit binary
        for (_ in 0..8) {
            if (n % 2 == 1) {
                binary.add(r'1')
            } else {
                binary.add(r'0')
            }
            n = n / 2
        }
        // Reverse to get correct order
        var result = ArrayList<Rune>()
        for (i in 0..binary.size) {
            result.add(binary[binary.size - 1 - i])
        }
        return result.toRuneArray().join("")
    }
