// Extension to help with binary conversion and string operations
extension Int64 {
    func toBinaryString(): String {
        if (this == 0) {
            return "0"
        }
        var num = this
        let binaryDigits = ArrayList<Rune>()
        while (num > 0) {
            binaryDigits.add(if (num % 2 == 0) { r'0' } else { r'1' })
            num = num / 2
        }
        binaryDigits.reverse()
        let runes = binaryDigits.toRuneArray()
        return String.fromRunes(runes)
    }
}

extension String {
    func split(delimiter: Rune): ArrayList<String> {
        let result = ArrayList<String>()
        let runes = this.toRuneArray()
        var start = 0
        for (i in 0..runes.size) {
            if (i == runes.size || runes[i] == delimiter) {
                let partRunes = runes[start..i]
                result.add(String.fromRunes(partRunes))
                start = i + 1
            }
        }
        return result
    }

    func join(parts: ArrayList<String>): String {
        if (parts.size == 0) {
            return ""
        }
        var result = parts[0]
        for (i in 1..parts.size) {
            result = result + this + parts[i]
        }
        return result
    }

    func isEmpty(): Bool {
        this.size() == 0
    }

    func size(): Int64 {
        this.runes().size()
    }
}

extension ArrayList<Rune> {
    func toRuneArray(): Array<Rune> {
        let arr = Array<Rune>(this.size)
        for (i in 0..this.size) {
            arr[i] = this[i]
        }
        return arr
    }

    func reverse() {
        let n = this.size
        for (i in 0..n/2) {
            let temp = this[i]
            this[i] = this[n - 1 - i]
            this[n - 1 - i] = temp
        }
    }
}

