class IpUtil {

    /*
    This is a class as tool for ip that can be used to obtain the local IP address, validate its validity, and also provides the functionality to retrieve the corresponding hostname.
    */

    public static func is_valid_ipv4(ip_address: String): Bool {
        /*
        Check if the given IP address is a valid IPv4 address.
        :param ip_address: String, the IP address to check
        :return: Bool, true if the IP address is valid, false otherwise
        >>> IpUtil.is_valid_ipv4('192.168.0.123')
        true
        >>> IpUtil.is_valid_ipv4('256.0.0.0')
        false

        */
        let parts = ip_address.split('.')
        if (parts.size != 4) {
            return false
        }

        for (part in parts) {
            if (part.isEmpty() || (part.size > 1 && part[0] == r'0')) {
                return false
            }

            var num: Int64 = 0
            for (c in part.runes()) {
                if (c < r'0' || c > r'9') {
                    return false
                }
                num = num * 10 + (c - r'0')
            }

            if (num > 255) {
                return false
            }
        }

        return true
    }

    public static func is_valid_ipv6(ip_address: String): Bool {
        /*
        Check if the given IP address is a valid IPv6 address.
        :param ip_address:String, the IP address to check
        :return:Bool, true if the IP address is valid, false otherwise
        >>> IpUtil.is_valid_ipv6('2001:0db8:85a3:0000:0000:8a2e:0370:7334')
        true
        >>> IpUtil.is_valid_ipv6('2001:0db8:85a3:::8a2e:0370:7334')
        false

        */
        let parts = ip_address.split(':')
        if (parts.size < 3 || parts.size > 8) {
            return false
        }

        var empty_count = 0
        var seen_empty = false
        for (i in 0..parts.size) {
            let part = parts[i]
            if (part.isEmpty()) {
                if (!seen_empty) {
                    seen_empty = true
                    empty_count += 1
                } else {
                    // More than one '::' 
                    return false
                }
            } else {
                if (part.size > 4) {
                    return false
                }
                for (c in part.runes()) {
                    if (!((c >= r'0' && c <= r'9') || (c >= r'a' && c <= r'f') || (c >= r'A' && c <= r'F'))) {
                        return false
                    }
                }
            }
        }

        if (parts.size == 8 && seen_empty) {
            // Full form has no '::'
            return false
        }
        if (parts.size < 8 && !seen_empty) {
            // Compressed form must have '::'
            return false
        }

        return true
    }

    public static func get_hostname(ip_address: String): Option<String> {
        /*
        Get the hostname associated with the given IP address.
        :param ip_address:String, the IP address to get the hostname for
        :return: String, the hostname associated with the IP address
        >>> IpUtil.get_hostname('110.242.68.3')
        'www.baidu.com'
        >>> IpUtil.get_hostname('10.0.0.1')
        None

        */
        // In real implementation, you would use gethostbyaddr or similar.
        // Since we don't have actual DNS lookup in this environment,
        // we'll simulate some known mappings.
        let fake_dns = HashMap<String, String>([
            ("110.242.68.3", "www.baidu.com"),
            ("8.8.8.8", "dns.google"),
            ("1.1.1.1", "one.one.one.one")
        ])

        match (fake_dns.get(ip_address)) {
            case Some(hostname) => Some(hostname)
            case None => None<String>()
        }
    }
}

