import std.collection.ArrayList
import std.math.abs

class KappaCalculator {

    /*
    This is a class as KappaCalculator, supporting to calculate Cohen's and Fleiss' kappa coefficient.
    */

    public static func kappa(testData: ArrayList<ArrayList<Int64>>, k: Int64): Float64 {
        /*
        Calculate the cohens kappa value of a k-dimensional matrix
        :param testData: The k-dimensional matrix that needs to calculate the cohens kappa value
        :param k: Int64, Matrix dimension
        :return:float, the cohens kappa value of the matrix
        >>> KappaCalculator.kappa(ArrayList<ArrayList<Int64>>([ArrayList<Int64>([2, 1, 1]), ArrayList<Int64>([1, 2, 1]), ArrayList<Int64>([1, 1, 2])]), 3)
        0.25
        */

        var total = 0.0
        var agreements = 0.0

        for (i in 0..testData.size) {
            let row = testData[i]
            for (j in 0..row.size) {
                agreements += row[j] * row[j]
                total += row[j]
            }
        }

        let pObserved = agreements / (total * total)
        var pExpected = 0.0

        // Calculate expected probability
        for (i in 0..k) {
            var rowSum = 0.0
            var colSum = 0.0
            for (j in 0..k) {
                rowSum += testData[i][j]
                colSum += testData[j][i]
            }
            pExpected += (rowSum * colSum) / (total * total)
        }

        if (pExpected == 1.0) {
            return 1.0
        }

        let kappa = (pObserved - pExpected) / (1.0 - pExpected)
        return kappa
    }

    public static func fleiss_kappa(testData: ArrayList<ArrayList<Int64>>, N: Int64, k: Int64, n: Int64): Float64 {
        /*
        Calculate the fliss kappa value of an N * k matrix
        :param testData: Input data matrix, N * k
        :param N: Int64, Number of samples
        :param k: Int64, Number of categories
        :param n: Int64, Number of raters
        :return: Float64, fleiss kappa value
        >>> KappaCalculator.fleiss_kappa(ArrayList<ArrayList<Int64>>([ArrayList<Int64>([0, 0, 0, 0, 14]),
        >>>                              ArrayList<Int64>([0, 2, 6, 4, 2]),
        >>>                              ArrayList<Int64>([0, 0, 3, 5, 6]),
        >>>                              ArrayList<Int64>([0, 3, 9, 2, 0]),
        >>>                              ArrayList<Int64>([2, 2, 8, 1, 1]),
        >>>                              ArrayList<Int64>([7, 7, 0, 0, 0]),
        >>>                              ArrayList<Int64>([3, 2, 6, 3, 0]),
        >>>                              ArrayList<Int64>([2, 5, 3, 2, 2]),
        >>>                              ArrayList<Int64>([6, 5, 2, 1, 0]),
        >>>                              ArrayList<Int64>([0, 2, 2, 3, 7])], 10, 5, 14)
        0.20993070442195522
        */

        var pjs = ArrayList<Float64>()
        for (j in 0..k) {
            var sum = 0.0
            for (i in 0..N) {
                sum += testData[i][j]
            }
            pjs.add(sum / (N * n))
        }

        var sumPjs2 = 0.0
        for (j in 0..k) {
            sumPjs2 += pjs[j] * pjs[j]
        }

        var Pis = ArrayList<Float64>()
        for (i in 0..N) {
            var sum = 0.0
            for (j in 0..k) {
                sum += testData[i][j] * (testData[i][j] - 1)
            }
            Pis.add(sum / (n * (n - 1)))
        }

        var Pbar = 0.0
        for (i in 0..N) {
            Pbar += Pis[i]
        }
        Pbar /= N

        var Pebar = sumPjs2

        if (Pebar == 1.0) {
            return 1.0
        }

        let kappa = (Pbar - Pebar) / (1.0 - Pebar)
        return kappa
    }
}

import std.collection.ArrayList
import std.math.abs

class KappaCalculator {

    /*
    This is a class as KappaCalculator, supporting to calculate Cohen's and Fleiss' kappa coefficient.
    */

    public static func kappa(testData: ArrayList<ArrayList<Int64>>, k: Int64): Float64 {
        /*
        Calculate the cohens kappa value of a k-dimensional matrix
        :param testData: The k-dimensional matrix that needs to calculate the cohens kappa value
        :param k: Int64, Matrix dimension
        :return:float, the cohens kappa value of the matrix
        >>> KappaCalculator.kappa(ArrayList<ArrayList<Int64>>([ArrayList<Int64>([2, 1, 1]), ArrayList<Int64>([1, 2, 1]), ArrayList<Int64>([1, 1, 2])]), 3)
        0.25
        */
        var total: Int64 = 0
        var agreement: Int64 = 0
        var chanceAgreement: Float64 = 0.0

        let nItems = testData.size
        var categoryTotals = ArrayList<Int64>([0 for _ in 0..k])

        // Calculate total number of observations and agreement count
        for (i in 0..nItems) {
            let row = testData[i]
            let sumRow = sum(row)
            total += sumRow
            let maxVal = row.max()
            for (j in 0..row.size) {
                if (row[j] == maxVal) {
                    agreement += row[j]
                    categoryTotals[j] += row[j]
                }
            }
        }

        // Calculate chance agreement probability
        for (i in 0..categoryTotals.size) {
            let p = (categoryTotals[i] as Float64) / (total as Float64)
            chanceAgreement += p * p
        }

        let pObserved = (agreement as Float64) / (total as Float64)
        let pExpected = chanceAgreement
        if (pExpected == 1.0) {
            return 1.0
        }

        return (pObserved - pExpected) / (1.0 - pExpected)
    }

    public static func fleiss_kappa(testData: ArrayList<ArrayList<Int64>>, N: Int64, k: Int64, n: Int64): Float64 {
        /*
        Calculate the fliss kappa value of an N * k matrix
        :param testData: Input data matrix, N * k
        :param N: Int64, Number of samples
        :param k: Int64, Number of categories
        :param n: Int64, Number of raters
        :return: Float64, fleiss kappa value
        >>> KappaCalculator.fleiss_kappa(ArrayList<ArrayList<Int64>>([ArrayList<Int64>([0, 0, 0, 0, 14]),
        >>>                              ArrayList<Int64>([0, 2, 6, 4, 2]),
        >>>                              ArrayList<Int64>([0, 0, 3, 5, 6]),
        >>>                              ArrayList<Int64>([0, 3, 9, 2, 0]),
        >>>                              ArrayList<Int64>([2, 2, 8, 1, 1]),
        >>>                              ArrayList<Int64>([7, 7, 0, 0, 0]),
        >>>                              ArrayList<Int64>([3, 2, 6, 3, 0]),
        >>>                              ArrayList<Int64>([2, 5, 3, 2, 2]),
        >>>                              ArrayList<Int64>([6, 5, 2, 1, 0]),
        >>>                              ArrayList<Int64>([0, 2, 2, 3, 7])], 10, 5, 14)
        0.20993070442195522
        */
        let nSquared = (n * (n - 1)) as Float64

        var pjList = ArrayList<Float64>([0.0 for _ in 0..k])
        var piList = ArrayList<Float64>([0.0 for _ in 0..N])

        // Calculate Pj (proportion of all assignments which were to category j)
        for (i in 0..N) {
            let row = testData[i]
            for (j in 0..k) {
                pjList[j] += row[j] as Float64
            }
        }

        for (j in 0..k) {
            pjList[j] /= (N * n) as Float64
        }

        // Calculate Pi (proportion of concordance among raters for item i)
        for (i in 0..N) {
            let row = testData[i]
            var sumRowSquared: Float64 = 0.0
            for (j in 0..k) {
                sumRowSquared += (row[j] as Float64) * (row[j] as Float64)
            }
            piList[i] = (sumRowSquared - n as Float64) / nSquared
        }

        // Mean of Pi values
        let pBar = piList.sum() / N as Float64

        // Sum of squared Pj values
        let pBarE = pjList.map({x: Float64 => x * x}).sum()

        if (1.0 - pBarE == 0.0) {
            return 1.0
        }

        return (pBar - pBarE) / (1.0 - pBarE)
    }
}

