        var total = 0.0
        for (i in 0..k) {
            for (j in 0..k) {
                total += testData[i][j].toFloat64()
            }
        }

        // Calculate observed agreement (Po)
        var po = 0.0
        for (i in 0..k) {
            po += testData[i][i].toFloat64()
        }
        po /= total

        // Calculate expected agreement (Pe)
        var pe = 0.0
        for (i in 0..k) {
