        >>>                              ArrayList<Int64>([0, 2, 2, 3, 7])], 10, 5, 14)
        0.20993070442195522
        */

        // Calculate Pj (proportion of ratings in each category)
        var Pj = ArrayList<Float64>()
        for (j in 0..k) {
            var sum = 0.0
            for (i in 0..N) {
                sum += testData[i][j].toFloat64()
            }
            Pj.add(sum / (N.toFloat64() * n.toFloat64()))
        }

        // Calculate Pe (expected agreement)
        var pe = 0.0
        for (j in 0..k) {
            pe += Pj[j] * Pj[j]
        }

        // Calculate Pi (observed agreement for each subject)
        var sum_pi = 0.0
        for (i in 0..N) {
            var sum_sq = 0.0
            for (j in 0..k) {
                sum_sq += testData[i][j].toFloat64() * testData[i][j].toFloat64()
            }
            sum_pi += (sum_sq - n.toFloat64()) / (n.toFloat64() * (n.toFloat64() - 1.0))
        }
        var po = sum_pi / N.toFloat64()

        // Calculate kappa
        if (pe == 1.0) {
            return 1.0
        }
        return (po - pe) / (1.0 - pe)
    }
