    }

    public static func create_board(BOARD_SIZE: ArrayList<Int64>, ICONS: ArrayList<String>): ArrayList<ArrayList<String>> {
        let rows = BOARD_SIZE[0]
        let cols = BOARD_SIZE[1]
        let board = ArrayList<ArrayList<String>>()

        let rand = Random()

        for (i in 0..rows) {
            let row = ArrayList<String>()
            for (j in 0..cols) {
                let randomIndex = rand.nextInt(ICONS.size) % ICONS.size
                row.add(ICONS[randomIndex])
            }
            board.add(row)
        }

        return board
    }

    public func is_valid_move(pos1: (Int64, Int64), pos2: (Int64, Int64)): Bool {
        let x1 = pos1[0]
        let y1 = pos1[1]
        let x2 = pos2[0]
        let y2 = pos2[1]

        // Check if positions are within board range
        if (x1 < 0 || x1 >= BOARD_SIZE[0] || y1 < 0 || y1 >= BOARD_SIZE[1] ||
            x2 < 0 || x2 >= BOARD_SIZE[0] || y2 < 0 || y2 >= BOARD_SIZE[1]) {
            return false
        }

        // Check if positions are the same
        if (x1 == x2 && y1 == y2) {
            return false
        }

        // Check if icons are the same
        if (board[x1][y1] != board[x2][y2]) {
            return false
        }

        // Check if positions have icons (not empty)
        if (board[x1][y1] == " " || board[x2][y2] == " ") {
            return false
        }

        // Check if there is a valid path
        return has_path(pos1, pos2)
    }

    public func has_path(pos1: (Int64, Int64), pos2: (Int64, Int64)): Bool {
        let x1 = pos1[0]
        let y1 = pos1[1]
        let x2 = pos2[0]
        let y2 = pos2[1]

        // Simple BFS implementation for path finding
        let visited = ArrayList<(Int64, Int64)>()
        let queue = ArrayList<(Int64, Int64)>()
        queue.add(pos1)

        // Directions: up, down, left, right
        let directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]

        while (queue.size > 0) {
            let current = queue[0]
            queue.remove(at: 0)

            if (current == pos2) {
                return true
            }

            if (MahjongConnect.contains(visited, current)) {
                continue
            }

            visited.add(current)

            for (dir in directions) {
                let newX = current[0] + dir[0]
                let newY = current[1] + dir[1]
                let newPos = (newX, newY)

                // Check bounds
                if (newX >= 0 && newX < BOARD_SIZE[0] && newY >= 0 && newY < BOARD_SIZE[1]) {
                    // Check if cell is empty or is the destination
                    if (board[newX][newY] == " " || newPos == pos2) {
                        if (!MahjongConnect.contains(visited, newPos)) {
                            queue.add(newPos)
                        }
                    }
                }
            }
        }

        return false
    }

    public static func contains(visited: ArrayList<(Int64, Int64)>, pos: (Int64, Int64)): Bool {
