import std.collection.*

class Manacher {
    let input_string: String

    public init(input_string: String) {
        this.input_string = input_string
    }

    public func palindromic_length(center: Int64, diff: Int64, string: String): Int64 {
        let len = string.size
        if (center - diff < 0 || center + diff >= len) {
            return 0
        }
        if (string[center - diff] != string[center + diff]) {
            return 0
        }
        return 1 + palindromic_length(center, diff + 1, string)
    }

    public func palindromic_string(): String {
        let original = this.input_string
        let len = original.size
        if (len == 0) {
            return ""
        }

        // Preprocess: insert '|' between each character and at both ends
        var processed = "|"
        for (i in 0..len) {
            processed = processed + original[i] + "|"
        }
        let processed_len = processed.size
        let palindrom_length = ArrayList<Int64>([])
        for (_ in 0..processed_len) {
            palindrom_length.add(0)
        }

        var center = 0
        var right = 0
        var max_len = 0
        var max_center = 0

        for (i in 0..processed_len) {
            let mirror = 2 * center - i

            if (i < right) {
                palindrom_length[i] = min(right - i, palindrom_length[mirror])
            }

            let length = palindromic_length(i, palindrom_length[i] + 1, processed)
