        :param diff: The difference between the center and the current position, Int64.
        :param string: The string to be searched, String.
        :return: The length of the palindromic substring, Int64.
        >>> manacher = Manacher('ababa')
        >>> manacher.palindromic_length(2, 1, 'a|b|a|b|a')
        2

        */
        let left = center - diff
        let right = center + diff

        if (left < 0 || right >= string.size) {
            return diff - 1
        }

        if (string[left] == string[right]) {
            return this.palindromic_length(center, diff + 1, string)
        } else {
            return diff - 1
        }
    }

    public func palindromic_string(): String {
        /*
        Finds the longest palindromic substring in the given string.
        :return: The longest palindromic substring, String.
        >>> manacher = Manacher('ababaxse')
        >>> manacher.palindromic_string()
        'ababa'

        */
        let original = this.input_string
        if (original.size == 0) {
            return ""
        }

        // Preprocess the string: insert '|' between each character and at the ends
        var processed = "|"
        for (i in 0..original.size) {
            processed = processed + original[i] + "|"
        }

        let n = processed.size
        let P = ArrayList<Int64>(Array<Int64>(n, 0))
        var center = 0
        var right = 0
        var max_len = 0
        var center_index = 0

        for (i in 0..n) {
            let mirror = 2 * center - i

            if (i < right) {
                P[i] = min(right - i, P[mirror])
            }

            // Try to expand palindrome centered at i
            let diff = P[i] + 1
            if (i - diff >= 0 && i + diff < n && processed[i - diff] == processed[i + diff]) {
                P[i] = this.palindromic_length(i, diff, processed)
            }

            // If palindrome centered at i extends past right, adjust center and right
            if (i + P[i] > right) {
                center = i
                right = i + P[i]

                if (P[i] > max_len) {
                    max_len = P[i]
                    center_index = i
                }
            }
        }

        // Extract the longest palindromic substring from original string
        let start = (center_index - max_len) / 2
        return original[start..start + max_len]
    }
}

