import std.collection.ArrayList
import std.collection.Array
import std.math.abs

class MetricsCalculator2 {

    /*
    The class provides to calculate Mean Reciprocal Rank (MRR) and Mean Average Precision (MAP) based on input data, where MRR measures the ranking quality and MAP measures the average precision.
    */

    public init() {}

    public static func mrr(data: Any): (Float64, ArrayList<Float64>) {
        let mrrList = ArrayList<Float64>()
        var totalMrr = 0.0

        match (data) {
            case item: (Array<Int64>, Int64) => {
                let rank = getFirstRelevantRank(item[0])
                let mrrValue = if (rank > 0) { 1.0 / Float64(rank) } else { 0.0 }
                mrrList.add(mrrValue)
                totalMrr = mrrValue
            }
            case items: ArrayList<(Array<Int64>, Int64)> => {
                for (item in items) {
                    let rank = getFirstRelevantRank(item[0])
                    let mrrValue = if (rank > 0) { 1.0 / Float64(rank) } else { 0.0 }
                    mrrList.add(mrrValue)
                    totalMrr += mrrValue
                }
                totalMrr /= Float64(items.size)
            }
            case _ => throw "Invalid input data format for mrr"
        }

        return (totalMrr, mrrList)
    }

    private static func getFirstRelevantRank(predictions: Array<Int64>): Int64 {
        for (i in 0..predictions.size) {
            if (predictions[i] == 1) {
                return Int64(i + 1)
            }
        }
        return 0 // No relevant item found
    }

    public static func map(data: Any): (Float64, ArrayList<Float64>) {
        let mapList = ArrayList<Float64>()
        var totalMap = 0.0

        match (data) {
            case item: (Array<Int64>, Int64) => {
                let ap = calculateAveragePrecision(item[0], item[1])
                mapList.add(ap)
                totalMap = ap
            }
            case items: ArrayList<(Array<Int64>, Int64)> => {
                for (item in items) {
                    let ap = calculateAveragePrecision(item[0], item[1])
                    mapList.add(ap)
                    totalMap += ap
                }
                totalMap /= Float64(items.size)
            }
            case _ => throw "Invalid input data format for map"
        }

        return (totalMap, mapList)
    }

    private static func calculateAveragePrecision(predictions: Array<Int64>, groundTruthCount: Int64): Float64 {
        var ap = 0.0
        var relevantCount = 0

        for (i in 0..predictions.size) {
            if (predictions[i] == 1) {
                relevantCount += 1
                ap += Float64(relevantCount) / Float64(i + 1)
            }
        }

        if (groundTruthCount == 0) {
            return 0.0
        }

        return ap / Float64(groundTruthCount)
    }
}

