                return (0.0, mrrList)
            }
        }

        let avgMrr = if (count > 0) { totalMrr / Float64(count) } else { 0.0 }
        return (avgMrr, mrrList)
    }

    private static func computeMrrForSingle(predictions: ArrayList<Int64>, groundTruthCount: Int64): Float64 {
        if (groundTruthCount <= 0) {
            return 0.0
        }

        for (idx in 0..predictions.size) {
            if (predictions[idx] == 1) {
                return 1.0 / Float64(idx + 1)
            }
        }
        return 0.0
    }

    public static func map(data: Any): (Float64, ArrayList<Float64>) {
        let mapList = ArrayList<Float64>()
        var totalMap: Float64 = 0.0
        var count: Int64 = 0

        match (data) {
            case (predictions: ArrayList<Int64>, groundTruthCount: Int64) => {
                let ap = computeApForSingle(predictions, groundTruthCount)
                mapList.add(ap)
                totalMap = ap
                count = 1
            }
            case dataList: ArrayList<(ArrayList<Int64>, Int64)> => {
                for (item in dataList) {
                    let (predictions, groundTruthCount) = item
                    let ap = computeApForSingle(predictions, groundTruthCount)
                    mapList.add(ap)
                    totalMap = totalMap + ap
                    count = count + 1
                }
            }
            case _ => {
                // Handle invalid input
                return (0.0, mapList)
            }
        }

        let avgMap = if (count > 0) { totalMap / Float64(count) } else { 0.0 }
        return (avgMap, mapList)
    }

    private static func computeApForSingle(predictions: ArrayList<Int64>, groundTruthCount: Int64): Float64 {
        if (groundTruthCount <= 0) {
            return 0.0
        }

        var numRel: Int64 = 0
        var sumPrecisions: Float64 = 0.0

        for (idx in 0..predictions.size) {
            if (predictions[idx] == 1) {
                numRel = numRel + 1
                let precisionAtK = Float64(numRel) / Float64(idx + 1)
                sumPrecisions = sumPrecisions + precisionAtK
            }
        }

        return sumPrecisions / Float64(groundTruthCount)
    }
}

