import std.collection.ArrayList
import std.random.Random

class MinesweeperGame {
    let n: Int64
    let k: Int64
    var minesweeper_map: ArrayList<ArrayList<String>>
    var player_map: ArrayList<ArrayList<String>>
    var score: Int64

    public init(n: Int64, k: Int64) {
        this.n = n
        this.k = k
        this.minesweeper_map = MinesweeperGame.generate_mine_sweeper_map(n, k)
        this.player_map = MinesweeperGame.generate_playerMap(n)
        this.score = 0
    }

    public static func generate_mine_sweeper_map(n: Int64, k: Int64): ArrayList<ArrayList<String>> {
        // Initialize map with zeros
        let map = ArrayList<ArrayList<String>>()
        for (i in 0..n) {
            let row = ArrayList<String>()
            for (j in 0..n) {
                row.add("0")
            }
            map.add(row)
        }

        // Place mines randomly
        var mines_placed = 0
        let random = Random()
        while (mines_placed < k) {
            let x = random.next() % n
            let y = random.next() % n
            if (map[x][y] != "X") {
                map[x][y] = "X"
                mines_placed += 1
            }
        }

        // Calculate numbers around mines
        for (i in 0..n) {
            for (j in 0..n) {
                if (map[i][j] != "X") {
                    let count = count_mines_around(map, i, j, n)
                    map[i][j] = count.toString()
                }
            }
        }

        return map
    }

    private static func count_mines_around(map: ArrayList<ArrayList<String>>, x: Int64, y: Int64, n: Int64): Int64 {
        var count = 0
        for (i in (x - 1)..(x + 2)) {
            for (j in (y - 1)..(y + 2)) {
                if (i >= 0 && i < n && j >= 0 && j < n && map[i][j] == "X") {
                    count += 1
                }
            }
        }
        return count
    }

    public static func generate_playerMap(n: Int64): ArrayList<ArrayList<String>> {
        let map = ArrayList<ArrayList<String>>()
        for (i in 0..n) {
            let row = ArrayList<String>()
            for (j in 0..n) {
                row.add("-")
            }
            map.add(row)
        }
        return map
    }

    public func check_won(map: ArrayList<ArrayList<String>>): Bool {
        for (i in 0..this.n) {
            for (j in 0..this.n) {
                if (map[i][j] == "-" && this.minesweeper_map[i][j] != "X") {
                    return false
                }
            }
        }
        return true
    }

    public func sweep(x: Int64, y: Int64): Any {
        if (x < 0 || x >= this.n || y < 0 || y >= this.n) {
            return this.player_map
        }

        if (this.minesweeper_map[x][y] == "X") {
            // Game over
            for (i in 0..this.n) {
                for (j in 0..this.n) {
                    if (this.minesweeper_map[i][j] == "X") {
                        this.player_map[i][j] = "X"
                    }
                }
            }
            return false
        } else {
            // Reveal the cell
            this.player_map[x][y] = this.minesweeper_map[x][y]
            this.score += 1

            // If it's a zero, reveal surrounding cells
            if (this.minesweeper_map[x][y] == "0") {
                reveal_zeros(x, y)
            }

            // Check if player has won
            if (check_won(this.player_map)) {
                return true
            } else {
                return this.player_map
            }
        }
    }

    private func reveal_zeros(x: Int64, y: Int64): Unit {
        for (i in (x - 1)..(x + 2)) {
            for (j in (y - 1)..(y + 2)) {
                if (i >= 0 && i < this.n && j >= 0 && j < this.n && 
                    this.player_map[i][j] == "-" && 
                    this.minesweeper_map[i][j] != "X") {

                    this.player_map[i][j] = this.minesweeper_map[i][j]
                    if (this.minesweeper_map[i][j] == "0") {
                        reveal_zeros(i, j)
                    }
                }
            }
        }
    }
}

