        for (_ in 0..n) {
            var row = ArrayList<String>()
            for (_ in 0..n) {
                row.add("0")
            }
            mine_map.add(row)
        }

        let random = Random()
        var mine_positions = ArrayList<(Int64, Int64)>()

        while (mine_positions.size < k) {
            let x = random.nextInt(from: 0, to: n)
            let y = random.nextInt(from: 0, to: n)
            let pos = (x, y)
            var found = false
            for (p in mine_positions) {
                if (p[0] == x && p[1] == y) {
                    found = true
                    break
                }
            }
            if (!found) {
                mine_positions.add(pos)
                mine_map[x][y] = "X"
            }
        }

        for (i in 0..n) {
            for (j in 0..n) {
                if (mine_map[i][j] != "X") {
                    var count = 0
                    for (dx in -1..2) {
                        for (dy in -1..2) {
                            let ni = i + dx
                            let nj = j + dy
                            if (ni >= 0 && ni < n && nj >= 0 && nj < n) {
                                if (mine_map[ni][nj] == "X") {
                                    count += 1
                                }
                            }
                        }
                    }
