        50

        */
        if (volume >= 0 && volume <= 100) {
            this.volume = volume
            return true
        }
        return false
    }

    public func shuffle(): Bool {
        /*
        Shuffles the playlist.
        :return: true if the playlist was shuffled, false if the playlist was empty.
        >>> musicPlayer = MusicPlayer()
        >>> musicPlayer.playlist = ArrayList<String>(["song1", "song2"])
        >>> musicPlayer.shuffle()
        true

        */
        if (playlist.size == 0) {
            return false
        }

        // Use a simple shuffle algorithm: Fisher-Yates-like approach manually implemented
        var i = playlist.size - 1
        while (i > 0) {
            let j = Random.nextInt(bound: i + 1)
            let temp = playlist[i]
            playlist[i] = playlist[j]
            playlist[j] = temp
            i = i - 1
        }
        return true
    }
}

