import std.convert.Parsable
import std.unicode.UnicodeStringExtension

class NumberWordFormatter {

    /*
    This is a class that provides to convert numbers into their corresponding English word representation, including handling the conversion of both the integer and decimal parts, and incorporating appropriate connectors and units.
    */

    let NUMBER: Array<String>
    let NUMBER_TEEN: Array<String>
    let NUMBER_TEN: Array<String>
    let NUMBER_MORE: Array<String>
    let NUMBER_SUFFIX: Array<String>

    public init() {
        /*
        Initialize NumberWordFormatter object.
        */
        this.NUMBER = ["", "ONE", "TWO", "THREE", "FOUR", "FIVE", "SIX", "SEVEN", "EIGHT", "NINE"]
        this.NUMBER_TEEN = ["TEN", "ELEVEN", "TWELVE", "THIRTEEN", "FOURTEEN", "FIFTEEN", "SIXTEEN", "SEVENTEEN",
                            "EIGHTEEN",
                            "NINETEEN"]
        this.NUMBER_TEN = ["TEN", "TWENTY", "THIRTY", "FORTY", "FIFTY", "SIXTY", "SEVENTY", "EIGHTY", "NINETY"]
        this.NUMBER_MORE = ["", "THOUSAND", "MILLION", "BILLION"]
        this.NUMBER_SUFFIX = ["k", "w", "", "m", "", "", "b", "", "", "t", "", "", "p", "", "", "e"]
    }

    public func format(x: Option<String>): String {
        match (x) {
            case Some<String>(str) => this.format_string(str)
            case None<String> => ""
        }
    }

    public func format_string(x: String): String {
        let parts = x.split(".")
        let integerPart = parts[0]
        let decimalPart = if (parts.size > 1) { parts[1] } else { "" }

        let result = this.trans_int(integerPart)

        if (decimalPart != "") {
            let decimalWords = this.trans_decimal(decimalPart)
            return "${result} AND ${decimalWords} ONLY"
        }
        return "${result} ONLY"
    }

    public func trans_int(s: String): String {
        if (s == "0") {
            return "ZERO"
        }

        let cleanS = s.trimStart('0')
        if (cleanS.isEmpty()) {
            return "ZERO"
        }

        let length = cleanS.size
        let groups = (length + 2) / 3
        let paddedLength = groups * 3
        let paddedS = cleanS.padStart(paddedLength, '0')

        var result = ArrayList<String>()
        for (i in 0..groups) {
            let start = i * 3
            let end = start + 3
            let groupStr = paddedS.substring(start, end)
            if (groupStr != "000") {
                let groupWord = this.trans_three(groupStr)
                let suffix = this.parse_more(groups - i - 1)
                result.add("${groupWord} ${suffix}".trim())
            }
        }

        return result.join(" ").trim()
    }

    public func trans_decimal(s: String): String {
        var words = ArrayList<String>()
        for (ch in s.runes()) {
            let digit = ch.toDigit().getOrThrow()
            words.add(this.NUMBER[digit])
        }
        return words.join(" ")
    }

    public func trans_two(s: String): String {
        let num = s.toInt().getOrThrow()
        if (num == 0) {
            return ""
        }
        if (num < 10) {
            return this.NUMBER[num]
        }
        if (num < 20) {
            return this.NUMBER_TEEN[num - 10]
        }
        let tens = num / 10
        let units = num % 10
        if (units == 0) {
            return this.NUMBER_TEN[tens - 1]
        }
        return "${this.NUMBER_TEN[tens - 1]} ${this.NUMBER[units]}"
    }

    public func trans_three(s: String): String {
        let num = s.toInt().getOrThrow()
        if (num == 0) {
            return ""
        }
        let hundreds = num / 100
        let remainder = num % 100
        var result = ArrayList<String>()
        if (hundreds > 0) {
            result.add("${this.NUMBER[hundreds]} HUNDRED")
        }
        if (remainder > 0) {
            result.add(this.trans_two(remainder.toString()))
        }
        return result.join(" AND ")
    }

    public func parse_more(i: Int64): String {
        if (i < this.NUMBER_MORE.size) {
            return this.NUMBER_MORE[i]
        }
        return ""
    }
}

