        */
        this.NUMBER = ["", "ONE", "TWO", "THREE", "FOUR", "FIVE", "SIX", "SEVEN", "EIGHT", "NINE"]
        this.NUMBER_TEEN = ["TEN", "ELEVEN", "TWELVE", "THIRTEEN", "FOURTEEN", "FIFTEEN", "SIXTEEN", "SEVENTEEN",
                            "EIGHTEEN",
                            "NINETEEN"]
        this.NUMBER_TEN = ["TEN", "TWENTY", "THIRTY", "FORTY", "FIFTY", "SIXTY", "SEVENTY", "EIGHTY", "NINETY"]
        this.NUMBER_MORE = ["", "THOUSAND", "MILLION", "BILLION"]
        this.NUMBER_SUFFIX = ["k", "w", "", "m", "", "", "b", "", "", "t", "", "", "p", "", "", "e"]
    }

    public func format(x: Option<String>): String {
        /*
        Converts a number into words format
        :param x: Option<String>, the number to be converted into words format
        :return: String, the number in words format
        >>> formatter = NumberWordFormatter()
        >>> formatter.format("123456")
        "ONE HUNDRED AND TWENTY THREE THOUSAND FOUR HUNDRED AND FIFTY SIX ONLY"
        */
        let value = x ?? ""
        return this.format_string(value)
    }

    public func format_string(x: String): String {
        /*
        Converts a string representation of a number into words format
        :param x: String, the string representation of a number
        :return: String, the number in words format
        >>> formatter = NumberWordFormatter()
        >>> formatter.format_string("123456")
        "ONE HUNDRED AND TWENTY THREE THOUSAND FOUR HUNDRED AND FIFTY SIX ONLY"
        */
        let parts = x.split('.')
        let integer_part = parts[0]
        let decimal_part = if (parts.size > 1) { parts[1] } else { "" }

        if (integer_part == "" && decimal_part == "") {
            return "ZERO ONLY"
        }

        let result = this.convert_integer(integer_part)

        if (decimal_part != "") {
            let decimal_words = this.convert_decimal(decimal_part)
            return "${result} AND ${decimal_words} ONLY"
        } else {
            return "${result} ONLY"
        }
    }

    private func convert_integer(s: String): String {
        if (s == "" || s == "0") {
            return "ZERO"
        }

        let clean_s = s.trimStart('0')
        if (clean_s == "") {
            return "ZERO"
        }

        let n = clean_s.size
        let groups = (n + 2) / 3
        let padded_size = groups * 3
        let padded_s = clean_s.padStart(padded_size, '0')

        var result_parts = ArrayList<String>()

        for (i in 0..groups) {
            let start_index = i * 3
            let end_index = start_index + 3
            let group_str = padded_s.substring(start_index, end_index)

            if (group_str != "000") {
                let group_words = this.trans_three(group_str)
                let suffix = this.parse_more(groups - i - 1)
                let group_with_suffix = if (suffix != "") { "${group_words} ${suffix}" } else { group_words }
                result_parts.add(group_with_suffix)
            }
        }

        return result_parts.join(" ")
    }

    private func convert_decimal(s: String): String {
        var words = ArrayList<String>()
        for (char in s.runes()) {
            let digit_str = char.toString()
            let digit = digit_str.toInt64() ?? 0
            words.add(this.NUMBER[digit.toIntNative()])
        }
        return words.join(" ")
    }

    public func trans_two(s: String): String {
        /*
        Converts a two-digit number into words format
        :param s: String, the two-digit number
        :return: String, the number in words format
        >>> formatter = NumberWordFormatter()
        >>> formatter.trans_two("23")
        "TWENTY THREE"
        */
        let tens_digit = s[0].toString().toInt64() ?? 0
        let ones_digit = s[1].toString().toInt64() ?? 0

        if (tens_digit == 0) {
            return this.NUMBER[ones_digit.toIntNative()]
        } else if (tens_digit == 1) {
            return this.NUMBER_TEEN[ones_digit.toIntNative()]
        } else {
            let tens_word = this.NUMBER_TEN[(tens_digit - 1).toIntNative()]
            if (ones_digit == 0) {
                return tens_word
            } else {
                return "${tens_word} ${this.NUMBER[ones_digit.toIntNative()]}"
            }
        }
    }

    public func trans_three(s: String): String {
        /*
        Converts a three-digit number into words format
        :param s: String, the three-digit number
        :return: String, the number in words format
        >>> formatter = NumberWordFormatter()
        >>> formatter.trans_three("123")
        "ONE HUNDRED AND TWENTY THREE"
        */
        let hundreds_digit = s[0].toString().toInt64() ?? 0
        let tens_ones_str = s.substring(1, 3)

        if (hundreds_digit == 0) {
            return this.trans_two(tens_ones_str)
        } else {
            let hundreds_word = this.NUMBER[hundreds_digit.toIntNative()]
            let tens_ones_word = this.trans_two(tens_ones_str)

            if (tens_ones_str == "00") {
                return "${hundreds_word} HUNDRED"
            } else {
                return "${hundreds_word} HUNDRED AND ${tens_ones_word}"
            }
        }
    }

    public func parse_more(i: Int64): String {
        /*
        Parses the thousand/million/billion suffix based on the index
        :param i: Int64, the index representing the magnitude (thousand, million, billion)
        :return: String, the corresponding suffix for the magnitude
        >>> formatter = NumberWordFormatter()
        >>> formatter.parse_more(1)
        "THOUSAND"
        */
        if (i >= 0 && i < this.NUMBER_MORE.size) {
            return this.NUMBER_MORE[i.toIntNative()]
        } else {
            return ""
        }
    }
}

