class NumberWordFormatter {

    /*
    This is a class that provides to convert numbers into their corresponding English word representation, including handling the conversion of both the integer and decimal parts, and incorporating appropriate connectors and units.
    */

    let NUMBER: Array<String>
    let NUMBER_TEEN: Array<String>
    let NUMBER_TEN: Array<String>
    let NUMBER_MORE: Array<String>
    let NUMBER_SUFFIX: Array<String>

    public init() {
        /*
        Initialize NumberWordFormatter object.
        */
        this.NUMBER = ["", "ONE", "TWO", "THREE", "FOUR", "FIVE", "SIX", "SEVEN", "EIGHT", "NINE"]
        this.NUMBER_TEEN = ["TEN", "ELEVEN", "TWELVE", "THIRTEEN", "FOURTEEN", "FIFTEEN", "SIXTEEN", "SEVENTEEN",
                            "EIGHTEEN",
                            "NINETEEN"]
        this.NUMBER_TEN = ["TEN", "TWENTY", "THIRTY", "FORTY", "FIFTY", "SIXTY", "SEVENTY", "EIGHTY", "NINETY"]
        this.NUMBER_MORE = ["", "THOUSAND", "MILLION", "BILLION"]
        this.NUMBER_SUFFIX = ["k", "w", "", "m", "", "", "b", "", "", "t", "", "", "p", "", "", "e"]
    }

    public func format(x: Option<String>): String {
        /*
        Converts a number into words format
        :param x: Option<String>, the number to be converted into words format
        :return: String, the number in words format
        >>> formatter = NumberWordFormatter()
        >>> formatter.format("123456")
        "ONE HUNDRED AND TWENTY THREE THOUSAND FOUR HUNDRED AND FIFTY SIX ONLY"
        */
        match (x) {
            case Some(s) => this.format_string(s) + " ONLY"
            case None => "INVALID INPUT"
        }
    }

    public func format_string(x: String): String {
        /*
        Converts a string representation of a number into words format
        :param x: String, the string representation of a number
        :return: String, the number in words format
        >>> formatter = NumberWordFormatter()
        >>> formatter.format_string("123456")
        "ONE HUNDRED AND TWENTY THREE THOUSAND FOUR HUNDRED AND FIFTY SIX ONLY"
        */
        // Remove any leading zeros and handle empty string
        if (x == "" || x == "0") {
            return "ZERO"
        }

        let clean_x = x.trim()
        if (clean_x == "") {
            return "ZERO"
        }

        // Handle negative numbers
        var is_negative = false
        var num_str = clean_x
        if (clean_x.startsWith("-")) {
            is_negative = true
            num_str = clean_x.substring(1)
        }

        // Split by decimal point if exists
        let parts = num_str.split('.')
        let integer_part = parts[0]
        var result = ""

        if (is_negative) {
            result = "MINUS "
        }

        result = result + this.convert_integer_part(integer_part)

        // Handle decimal part if exists
        if (parts.size > 1 && parts[1] != "") {
            let decimal_part = parts[1]
            result = result + " POINT " + this.convert_decimal_part(decimal_part)
        }

        return result
    }

    private func convert_integer_part(s: String): String {
        if (s == "" || s == "0") {
            return "ZERO"
        }

        // Remove leading zeros
        var clean_s = s
        while (clean_s.size > 1 && clean_s.startsWith("0")) {
            clean_s = clean_s.substring(1)
        }

        if (clean_s == "") {
            return "ZERO"
        }

        // Pad with zeros to make length multiple of 3
        while (clean_s.size % 3 != 0) {
            clean_s = "0" + clean_s
        }

        var result = ""
        let groups = clean_s.size / 3
        for (i in 0..groups) {
            let start = i * 3
            let end = start + 3
            let group = clean_s.substring(start, end)

            if (group != "000") {
                let group_words = this.trans_three(group)
                if (group_words != "") {
                    if (result != "") {
                        result = result + " "
                    }
                    result = result + group_words
                    let magnitude = groups - i - 1
                    if (magnitude > 0) {
                        result = result + " " + this.parse_more(magnitude)
                    }
                }
            }
        }

        return result
    }

    private func convert_decimal_part(s: String): String {
        var result = ""
        for (i in 0..s.size) {
            let digit_char = s.substring(i, i + 1)
            let digit = digit_char.toInt() ?? 0
            if (result != "") {
                result = result + " "
            }
            result = result + this.NUMBER[digit]
        }
        return result
    }

    public func trans_two(s: String): String {
        /*
        Converts a two-digit number into words format
        :param s: String, the two-digit number
        :return: String, the number in words format
        >>> formatter = NumberWordFormatter()
        >>> formatter.trans_two("23")
        "TWENTY THREE"
        */
        // Pad with leading zero if needed
        var padded_s = s
        if (s.size == 1) {
            padded_s = "0" + s
        }

        let first = padded_s.substring(0, 1).toInt() ?? 0
        let second = padded_s.substring(1, 2).toInt() ?? 0

        if (first == 0) {
            return this.NUMBER[second]
        } else if (first == 1) {
            return this.NUMBER_TEEN[second]
        } else {
            if (second == 0) {
                return this.NUMBER_TEN[first - 1]
            } else {
                return this.NUMBER_TEN[first - 1] + " " + this.NUMBER[second]
            }
        }
    }

    public func trans_three(s: String): String {
        /*
        Converts a three-digit number into words format
        :param s: String, the three-digit number
        :return: String, the number in words format
        >>> formatter = NumberWordFormatter()
        >>> formatter.trans_three("123")
        "ONE HUNDRED AND TWENTY THREE"
        */
        let first = s.substring(0, 1).toInt() ?? 0
        let last_two = s.substring(1, 3)
        let last_two_value = last_two.toInt() ?? 0

        if (first == 0) {
            return this.trans_two(last_two)
        }

        var result = this.NUMBER[first] + " HUNDRED"

        if (last_two_value != 0) {
            result = result + " AND " + this.trans_two(last_two)
        }

        return result
    }

    public func parse_more(i: Int64): String {
        /*
        Parses the thousand/million/billion suffix based on the index
        :param i: Int64, the index representing the magnitude (thousand, million, billion)
        :return: String, the corresponding suffix for the magnitude
        >>> formatter = NumberWordFormatter()
        >>> formatter.parse_more(1)
        "THOUSAND"
        */
        if (i < this.NUMBER_MORE.size) {
            return this.NUMBER_MORE[i]
        }
        return ""
    }
}

