        >>> formatter = NumberWordFormatter()
        >>> formatter.format("123456")
        "ONE HUNDRED AND TWENTY THREE THOUSAND FOUR HUNDRED AND FIFTY SIX ONLY"
        */
        match (x) {
            case Some<String>(value) => this.format_string(value)
            case None<String> => "ZERO ONLY"
        }
    }

    public func format_string(x: String): String {
        /*
        Converts a string representation of a number into words format
        :param x: String, the string representation of a number
        :return: String, the number in words format
        >>> formatter = NumberWordFormatter()
        >>> formatter.format_string("123456")
        "ONE HUNDRED AND TWENTY THREE THOUSAND FOUR HUNDRED AND FIFTY SIX ONLY"
        */
        if (x.isEmpty()) {
            return "ZERO ONLY"
        }

        let parts = x.split('.')
        let integer_part = parts[0]
        let decimal_part = if (parts.size > 1) { parts[1] } else { "" }

        let result = this.convert_integer_part(integer_part)
        if (decimal_part.isNotEmpty()) {
            let decimal_words = this.convert_decimal_part(decimal_part)
            return "${result} AND ${decimal_words} ONLY"
        } else {
            return "${result} ONLY"
        }
    }

    private func convert_integer_part(s: String): String {
        if (s.isEmpty() || s == "0") {
            return "ZERO"
        }

        var num_str = s
        while (num_str.size % 3 != 0) {
            num_str = "0${num_str}"
        }

        let chunks = ArrayList<String>()
        for (i in 0..num_str.size:3) {
            chunks.add(num_str.substring(i, i + 3))
        }

        let n = chunks.size
        var result_parts = ArrayList<String>()

        for (i in 0..n) {
            let chunk = chunks[i]
            if (chunk != "000") {
                let chunk_word = this.trans_three(chunk)
                let suffix = this.parse_more(n - i - 1)
                if (suffix.isNotEmpty()) {
                    result_parts.add("${chunk_word} ${suffix}")
                } else {
                    result_parts.add(chunk_word)
                }
            }
        }

        var result = ""
        for (i in 0..result_parts.size) {
            if (i > 0 && result.isNotEmpty() && result_parts[i].isNotEmpty()) {
                result = "${result} "
            }
            result = "${result}${result_parts[i]}"
        }

        return result
    }

