        let ones_digit = s.toRuneArray()[1] - r'0'

        if (tens_digit == 0) {
            return this.NUMBER[ones_digit]
        } else if (tens_digit == 1) {
            return this.NUMBER_TEEN[ones_digit]
        } else {
            if (ones_digit == 0) {
                return this.NUMBER_TEN[tens_digit - 1]
            } else {
                return "${this.NUMBER_TEN[tens_digit - 1]} ${this.NUMBER[ones_digit]}"
