    public func format_string(x: String): String {
        let parts = x.split('.')
        let integer_part = parts[0]
        let decimal_part = if (parts.size > 1) { parts[1] } else { "" }

        let integer_words = this.convert_integer(integer_part)
        let decimal_words = if (decimal_part != "") {
            " AND " + this.convert_decimal(decimal_part) + " CENTS"
        } else {
            " ONLY"
        }

        integer_words + decimal_words
    }

    private func convert_integer(s: String): String {
        if (s == "0") {
            return "ZERO"
        }

        var result: String = ""
        var i: Int64 = 0
        var segment_index: Int64 = 0

        while (i < s.size) {
            let remaining = s.size - i
            let take = remaining % 3
            let chunk_size = if (take == 0) { 3 } else { take }
            let chunk = s.substring(i, i + chunk_size)

            let words = this.trans_three(chunk)
            if (words != "") {
                let suffix = this.parse_more((s.size - i - 1) / 3)
                result = words + (if (suffix != "") { " " + suffix } else { "" }) + 
                         (if (result != "") { " " + result } else { "" })
            }

            i += chunk_size
            segment_index += 1
        }

