        let result = if (decimal_part != "") {
            let decimal_words = this.trans_decimal(decimal_part)
            "${integer_words} AND ${decimal_words} ONLY"
        } else {
            "${integer_words} ONLY"
        }

        return result
    }

    private func trans_integer(s: String): String {
        let clean_s = s.trim()
        if (clean_s == "" || clean_s == "0") {
            return "ZERO"
        }

        let n = clean_s.size
        let groups = (n + 2) / 3  // number of 3-digit groups
        let padded_length = groups * 3
        let padded_s = clean_s.padStart(padded_length, '0')

        var result_parts = ArrayList<String>()
        for (i in 0..groups) {
            let start_index = i * 3
            let end_index = start_index + 3
            let group_str = padded_s.substring(start_index, end_index)
            if (group_str != "000") {
                let group_words = this.trans_three(group_str)
                let suffix = this.parse_more(groups - i - 1)
                let group_result = if (suffix != "") {
                    "${group_words} ${suffix}"
                } else {
                    group_words
                }
                result_parts.add(group_result)
            }
        }

        return result_parts.join(" ")
    }

    private func trans_decimal(s: String): String {
        let digits = s.toRuneArray()
        var words = ArrayList<String>()
        for (r in digits) {
            let d = r - r'0'
            words.add(this.NUMBER[d])
        }
        words.add("CENTS")
        return words.join(" ")
    }

    public func trans_two(s: String): String {
        /*
        Converts a two-digit number into words format
        :param s: String, the two-digit number
        :return: String, the number in words format
        >>> formatter = NumberWordFormatter()
        >>> formatter.trans_two("23")
        "TWENTY THREE"
        */
        let tens_place = s[0] - r'0'
        let ones_place = s[1] - r'0'

        if (tens_place == 0) {
            return this.NUMBER[ones_place]
        } else if (tens_place == 1) {
            return this.NUMBER_TEEN[ones_place]
        } else {
            let tens_word = this.NUMBER_TEN[tens_place - 1]
            let ones_word = if (ones_place != 0) { this.NUMBER[ones_place] } else { "" }
            return if (ones_word != "") { "${tens_word} ${ones_word}" } else { tens_word }
        }
    }

    public func trans_three(s: String): String {
        /*
        Converts a three-digit number into words format
        :param s: String, the three-digit number
        :return: String, the number in words format
        >>> formatter = NumberWordFormatter()
        >>> formatter.trans_three("123")
        "ONE HUNDRED AND TWENTY THREE"
        */
        let hundreds_place = s[0] - r'0'
        let remainder = s.substring(1)

        var result = ""
        if (hundreds_place != 0) {
            result += this.NUMBER[hundreds_place] + " HUNDRED"
        }

        let tens_and_ones = this.trans_two(remainder)
        if (tens_and_ones != "") {
            if (result != "") {
                result += " AND "
            }
            result += tens_and_ones
        }

        return result
    }

    public func parse_more(i: Int64): String {
        /*
        Parses the thousand/million/billion suffix based on the index
        :param i: Int64, the index representing the magnitude (thousand, million, billion)
        :return: String, the corresponding suffix for the magnitude
        >>> formatter = NumberWordFormatter()
        >>> formatter.parse_more(1)
        "THOUSAND"
        */
        if (i >= 0 && i < this.NUMBER_MORE.size) {
            return this.NUMBER_MORE[i]
        }
        return ""
    }
}

