        :return: String, the input string with numeric character references replaced with their corresponding Unicode characters.
        >>> unescaper = NumericEntityUnescaper()
        >>> unescaper.replace("&#65;&#66;&#67;")
        'ABC'

        */
        let runes = string.toRuneArray()
        var result = ArrayList<Rune>()
        var i: Int64 = 0
        let size = runes.size

        while (i < size) {
            if (runes[i] == r'&' && i + 1 < size && runes[i + 1] == r'#') {
                // Start of a numeric entity
                var j = i + 2
                var is_hex = false
                if (j < size && runes[j] == r'x') {
                    is_hex = true
                    j += 1
                }

                let start = j
                while (j < size && runes[j] != r';') {
                    j += 1
                }

                if (j >= size) {
                    // No closing ';', treat as literal
                    result.add(runes[i])
                    i += 1
                    continue
                }

                let num_str = string.substring(start, j)
                var code_point: Int64 = 0
                if (is_hex) {
                    code_point = Int64.parse(num_str, radix: 16) ?? 0
                } else {
                    code_point = Int64.parse(num_str, radix: 10) ?? 0
                }

                // Convert code point to Rune
                let rune = Rune.fromCodePoint(code_point)
                result.add(rune)
                i = j + 1
            } else {
                result.add(runes[i])
                i += 1
            }
        }

        // Convert ArrayList<Rune> back to String
        var s = ""
        for (r in result) {
            s = s + r.toString()
        }
        return s
    }

