import std.collection.ArrayList
import std.collection.HashSet

class PushBoxGame {

    /*
    This class implements a functionality of a sokoban game, where the player needs to move boxes to designated targets in order to win.
    */

    let map: ArrayList<ArrayList<String>>
    var player_row: Int64
    var player_col: Int64
    let targets: ArrayList<ArrayList<Int64>>
    let boxes: ArrayList<ArrayList<Int64>>
    var target_count: Int64
    var is_game_over: Bool

    public init(map: ArrayList<ArrayList<String>>) {
        /*
        Initialize the push box game with the map and various attributes.
        :param map: ArrayList<ArrayList<String>>, the map of the push box game, represented as a list of strings. 
            Each character on the map represents a different element, including the following:
            - '#' represents a wall that neither the player nor the box can pass through;
            - 'O' represents the initial position of the player;
            - 'G' represents the target position;
            - 'X' represents the initial position of the box.
        >>> map = ArrayList<ArrayList<String>>([ArrayList<String>(["#", "#", "#", "#", "#"]), ArrayList<String>(["#", "O", " ", " ", "#"]), ArrayList<String>(["#", " ", "X", " ", "#"]), ArrayList<String>(["#", " ", " ", "G", "#"]), ArrayList<String>(["#", "#", "#", "#", "#"])])
        >>> game = PushBoxGame(map) 
        */
        this.map = map
        this.player_row = 0
        this.player_col = 0
        this.targets = ArrayList<ArrayList<Int64>>()
        this.boxes = ArrayList<ArrayList<Int64>>()
        this.target_count = 0
        this.is_game_over = false

        func init_game() {
            /*
            Initialize the game by setting the positions of the player, targets, and boxes based on the map.
            >>> game = PushBoxGame(ArrayList<ArrayList<String>>([ArrayList<String>(["#", "#", "#", "#", "#"]), ArrayList<String>(["#", "O", " ", " ", "#"]), ArrayList<String>(["#", " ", "X", " ", "#"]), ArrayList<String>(["#", " ", " ", "G", "#"]), ArrayList<String>(["#", "#", "#", "#", "#"])])) 
            >>> game.targets
            [[3, 3]]
            >>> game.boxes
            [[2, 2]]
            >>> game.player_row
            1
            >>> game.player_col
            1
            */
            for (row in 0..map.size) {
                for (col in 0..map[row].size) {
                    let cell = map[row][col]
                    if (cell == "O") {
                        this.player_row = row
                        this.player_col = col
                    } else if (cell == "G") {
                        this.targets.add(ArrayList<Int64>([row, col]))
                        this.target_count += 1
                    } else if (cell == "X") {
                        this.boxes.add(ArrayList<Int64>([row, col]))
                    }
                }
            }
        }
        init_game()
    }

    public func check_win(): Bool {
        /*
        Check if the game is won. The game is won when all the boxes are placed on target positions.
        And update the value of this.is_game_over.
        :return this.is_game_over: true if all the boxes are placed on target positions, or false otherwise.
        >>> game = PushBoxGame(ArrayList<ArrayList<String>>([ArrayList<String>(["#", "#", "#", "#", "#"]), ArrayList<String>(["#", "O", " ", " ", "#"]), ArrayList<String>(["#", " ", "X", " ", "#"]), ArrayList<String>(["#", " ", " ", "G", "#"]), ArrayList<String>(["#", "#", "#", "#", "#"])])) 
        >>> game.check_win()
        false
        */
        let box_positions = HashSet<ArrayList<Int64>>()
        for (box in this.boxes) {
            box_positions.add(box)
        }

        var count = 0
        for (target in this.targets) {
            if (box_positions.contains(target)) {
                count += 1
            }
        }

        this.is_game_over = (count == this.target_count)
        return this.is_game_over
    }

    public func move(direction: String): Bool {
        /*
        Move the player based on the specified direction and check if the game is won.
        :param direction: String, the direction of the player's movement. 
            It can be 'w', 's', 'a', or 'd' representing up, down, left, or right respectively.

        :return: true if the game is won, false otherwise.
        >>> game = PushBoxGame(ArrayList<ArrayList<String>>([ArrayList<String>(["#", "#", "#", "#", "#"]), ArrayList<String>(["#", "O", " ", " ", "#"]), ArrayList<String>(["#", " ", "X", " ", "#"]), ArrayList<String>(["#", " ", " ", "G", "#"]), ArrayList<String>(["#", "#", "#", "#", "#"])]))       
        >>> game.print_map()
        # # # # # 
        # O     #
        #   X   #
        #     G #
        # # # # #
        >>> game.move('d')
        false
        >>> game.move('s')   
        false
        >>> game.move('a')   
        false
        >>> game.move('s') 
        false
        >>> game.move('d') 
        true
        */
        var delta_row = 0
        var delta_col = 0

        if (direction == "w") {
            delta_row = -1
        } else if (direction == "s") {
            delta_row = 1
        } else if (direction == "a") {
            delta_col = -1
        } else if (direction == "d") {
            delta_col = 1
        } else {
            return false
        }

        let new_player_row = this.player_row + delta_row
        let new_player_col = this.player_col + delta_col

        // Check boundaries
        if (new_player_row < 0 || new_player_row >= this.map.size || 
            new_player_col < 0 || new_player_col >= this.map[new_player_row].size) {
            return false
        }

        let next_cell = this.map[new_player_row][new_player_col]
        if (next_cell == "#") {
            return false
        }

        // Check if there is a box at the new position
        var box_index = -1
        for (i in 0..this.boxes.size) {
            let box = this.boxes[i]
            if (box[0] == new_player_row && box[1] == new_player_col) {
                box_index = i
                break
            }
        }

        if (box_index != -1) {
            // There is a box, try to push it
            let new_box_row = new_player_row + delta_row
            let new_box_col = new_player_col + delta_col

            // Check boundaries for the box
            if (new_box_row < 0 || new_box_row >= this.map.size || 
                new_box_col < 0 || new_box_col >= this.map[new_box_row].size) {
                return false
            }

            let box_next_cell = this.map[new_box_row][new_box_col]
            if (box_next_cell == "#") {
                return false
            }

            // Check if there is another box at the new box position
            for (box in this.boxes) {
                if (box[0] == new_box_row && box[1] == new_box_col) {
                    return false
                }
            }

            // Move the box
            this.boxes[box_index][0] = new_box_row
            this.boxes[box_index][1] = new_box_col
        }

        // Move the player
        this.player_row = new_player_row
        this.player_col = new_player_col

        // Check if the game is won
        return this.check_win()
    }

    public func print_map(): Unit {
        let box_positions = HashSet<ArrayList<Int64>>()
        for (box in this.boxes) {
            box_positions.add(box)
        }

        let target_positions = HashSet<ArrayList<Int64>>()
        for (target in this.targets) {
            target_positions.add(target)
        }

        for (row in 0..this.map.size) {
            for (col in 0..this.map[row].size) {
                if (row == this.player_row && col == this.player_col) {
                    print("O ")
                } else {
                    var is_box = false
                    for (box in this.boxes) {
                        if (box[0] == row && box[1] == col) {
                            is_box = true
                            break
                        }
                    }

                    var is_target = false
                    for (target in this.targets) {
                        if (target[0] == row && target[1] == col) {
                            is_target = true
                            break
                        }
                    }

                    if (is_box) {
                        print("X ")
                    } else if (is_target) {
                        print("G ")
                    } else {
                        print("${this.map[row][col]} ")
                    }
                }
            }
            println()
        }
    }
}

