        :return this.is_game_over: true if all the boxes are placed on target positions, or false otherwise.
        >>> game = PushBoxGame(ArrayList<ArrayList<String>>([ArrayList<String>(["#", "#", "#", "#", "#"]), ArrayList<String>(["#", "O", " ", " ", "#"]), ArrayList<String>(["#", " ", "X", " ", "#"]), ArrayList<String>(["#", " ", " ", "G", "#"]), ArrayList<String>(["#", "#", "#", "#", "#"])])) 
        >>> game.check_win()
        false
        */
        let box_positions = HashSet<ArrayList<Int64>>()
        for (box in this.boxes) {
            box_positions.add(box)
        }

        var count = 0
        for (target in this.targets) {
            if (box_positions.contains(target)) {
                count += 1
            }
        }

        this.is_game_over = (count == this.target_count)
        return this.is_game_over
    }

    public func move(direction: String): Bool {
        /*
        Move the player based on the specified direction and check if the game is won.
        :param direction: String, the direction of the player's movement. 
            It can be 'w', 's', 'a', or 'd' representing up, down, left, or right respectively.

        :return: true if the game is won, false otherwise.
        >>> game = PushBoxGame(ArrayList<ArrayList<String>>([ArrayList<String>(["#", "#", "#", "#", "#"]), ArrayList<String>(["#", "O", " ", " ", "#"]), ArrayList<String>(["#", " ", "X", " ", "#"]), ArrayList<String>(["#", " ", " ", "G", "#"]), ArrayList<String>(["#", "#", "#", "#", "#"])]))       
        >>> game.print_map()
        # # # # # 
        # O     #
        #   X   #
        #     G #
        # # # # #
        >>> game.move('d')
        false
        >>> game.move('s')   
        false
        >>> game.move('a')   
        false
        >>> game.move('s') 
        false
        >>> game.move('d') 
        true
        */

        var delta_row: Int64 = 0
        var delta_col: Int64 = 0

        if (direction == "w") {
            delta_row = -1
        } else if (direction == "s") {
            delta_row = 1
        } else if (direction == "a") {
            delta_col = -1
        } else if (direction == "d") {
            delta_col = 1
        } else {
            return false // Invalid direction
        }

        let new_player_row = this.player_row + delta_row
        let new_player_col = this.player_col + delta_col

        // Check boundaries
        if (new_player_row < 0 || new_player_row >= this.map.size || new_player_col < 0 || new_player_col >= this.map[new_player_row].size) {
            return false
        }

        let next_cell = this.map[new_player_row][new_player_col]

        // Check for wall
        if (next_cell == "#") {
            return false
        }

        // Check if there's a box in the direction
        var box_index: Int64 = -1
        for (i in 0..this.boxes.size) {
            let box = this.boxes[i]
            if (box[0] == new_player_row && box[1] == new_player_col) {
                box_index = i
                break
            }
        }

        if (box_index != -1) {
            // There's a box, try to push it
            let new_box_row = new_player_row + delta_row
            let new_box_col = new_player_col + delta_col

            // Check boundaries for the box
            if (new_box_row < 0 || new_box_row >= this.map.size || new_box_col < 0 || new_box_col >= this.map[new_box_row].size) {
                return false
            }

            let box_next_cell = this.map[new_box_row][new_box_col]

            // Check for wall or another box
            if (box_next_cell == "#" || box_next_cell == "X") {
                // Check if another box is already there
                for (box in this.boxes) {
                    if (box[0] == new_box_row && box[1] == new_box_col) {
                        return false
                    }
                }
                return false
            }

            // Move the box
            this.boxes[box_index][0] = new_box_row
            this.boxes[box_index][1] = new_box_col
        }

        // Move the player
        this.player_row = new_player_row
        this.player_col = new_player_col

        // Check win condition
        return this.check_win()
    }

    public func print_map(): Unit {
        /*
        Print the current map state.
        */
        var display_map = ArrayList<ArrayList<String>>()
        for (row in 0..this.map.size) {
            display_map.add(ArrayList<String>())
            for (col in 0..this.map[row].size) {
                display_map[row].add(this.map[row][col])
            }
        }

        // Place targets
        for (target in this.targets) {
            let r = target[0]
            let c = target[1]
            if (display_map[r][c] == " ") {
                display_map[r][c] = "G"
            }
        }

        // Place boxes
        for (box in this.boxes) {
            let r = box[0]
            let c = box[1]
            if (display_map[r][c] == "G") {
                display_map[r][c] = "*"
            } else {
                display_map[r][c] = "X"
            }
        }

        // Place player
        if (display_map[this.player_row][this.player_col] == "G") {
            display_map[this.player_row][this.player_col] = "+"
        } else {
            display_map[this.player_row][this.player_col] = "O"
        }

        // Print the map
        for (row in display_map) {
            var line = ""
            for (cell in row) {
                line = line + cell + " "
            }
            println(line.trimEnd())
        }
    }
}

import std.regex.Regex
import std.collection.ArrayList

class RegexUtils {

    /*
    The class provides to match, find all occurrences, split, and substitute text using regular expressions. It also includes predefined patterns, validating phone numbers and extracting email addresses.
    */

    public func match_regex(pattern: String, text: String): Bool {
        let regex = Regex(pattern)
        return regex.matches(text)
    }

    public func findall(pattern: String, text: String): ArrayList<String> {
        let regex = Regex(pattern)
        let matches = regex.findAll(text)
        let result = ArrayList<String>()
        for (m in matches) {
            result.add(m.value)
        }
        return result
    }

    public func split(pattern: String, text: String): ArrayList<String> {
        let regex = Regex(pattern)
        let splits = regex.split(text)
        let result = ArrayList<String>()
        for (s in splits) {
            result.add(s)
        }
        return result
    }

    public func sub(pattern: String, replacement: String, text: String): String {
        let regex = Regex(pattern)
        return regex.replace(text, replacement)
    }

    public func generate_email_pattern(): String {
        return #"\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b"#
    }

    public func generate_phone_number_pattern(): String {
        return #"\b\d{3}-\d{3}-\d{4}\b"#
    }

    public func generate_split_sentences_pattern(): String {
        return #"[.!?][\s]{1,2}(?=[A-Z])"#
    }

    public func split_sentences(text: String): ArrayList<String> {
        let pattern = this.generate_split_sentences_pattern()
        let regex = Regex(pattern)
        let parts = regex.splitWithSeparator(text)
        let result = ArrayList<String>()

        var i = 0
        while (i < parts.size) {
            let part = parts[i]
            if (part.length > 0 && (part[0] == '.' || part[0] == '!' || part[0] == '?')) {
                if (result.size > 0) {
                    let prev = result[result.size - 1]
                    result[result.size - 1] = prev + part.trim()
                } else {
                    result.add(part.trim())
                }
                i += 1
            } else {
                result.add(part.trim())
                i += 1
            }
        }

        // Trim any trailing punctuation from all except last sentence
        var j = 0
        while (j < result.size - 1) {
            let s = result[j]
            if (s.length > 0) {
                let lastChar = s[s.length - 1]
                if (lastChar == '.' || lastChar == '!' || lastChar == '?') {
                    result[j] = s.substring(0, s.length - 1)
                }
            }
            j += 1
        }

        return result
    }

    public func validate_phone_number(phone_number: String): Bool {
        let pattern = this.generate_phone_number_pattern()
        return this.match_regex(pattern, phone_number)
    }

    public func extract_email(text: String): ArrayList<String> {
        let pattern = this.generate_email_pattern()
        return this.findall(pattern, text)
    }
}

