import std.random.Random

class Snake {
    var length: Int64
    let SCREEN_WIDTH: Int64
    let SCREEN_HEIGHT: Int64
    let BLOCK_SIZE: Int64
    var positions: ArrayList<ArrayList<Int64>>
    var score: Int64
    var food_position: ArrayList<Int64>

    public init(SCREEN_WIDTH: Int64, SCREEN_HEIGHT: Int64, BLOCK_SIZE: Int64, food_position: ArrayList<Int64>) {
        this.length = 1
        this.SCREEN_WIDTH = SCREEN_WIDTH
        this.SCREEN_HEIGHT = SCREEN_HEIGHT
        this.BLOCK_SIZE = BLOCK_SIZE
        this.positions = ArrayList<ArrayList<Int64>>([ArrayList<Int64>([SCREEN_WIDTH / 2, SCREEN_HEIGHT / 2])])
        this.score = 0
        this.food_position = food_position
    }

    public func move(direction: ArrayList<Int64>): Unit {
        // Get current head position
        let head = this.positions[0]
        let new_x = head[0] + direction[0] * this.BLOCK_SIZE
        let new_y = head[1] + direction[1] * this.BLOCK_SIZE

        // Create new head position
        let new_head = ArrayList<Int64>([new_x, new_y])

        // Check if snake eats food
        if (new_head[0] == this.food_position[0] && new_head[1] == this.food_position[1]) {
            this.eat_food()
        } else {
            // Add new head
            this.positions.add(new_head, at: 0)
            // Remove tail
            this.positions.remove(at: this.positions.size - 1)
        }

        // Check for collision with self
        for (i in 1..this.positions.size) {
            let segment = this.positions[i]
            if (new_head[0] == segment[0] && new_head[1] == segment[1]) {
                this.reset()
                return
            }
        }
    }

    public func random_food_position(): Unit {
        let random = Random()
        var new_food_x: Int64
        var new_food_y: Int64
        var on_snake: Bool

        do {
            on_snake = false
            new_food_x = (random.nextInt() % (this.SCREEN_WIDTH / this.BLOCK_SIZE)) * this.BLOCK_SIZE
            new_food_y = (random.nextInt() % (this.SCREEN_HEIGHT / this.BLOCK_SIZE)) * this.BLOCK_SIZE

            // Check if new food position is on snake
            for (segment in this.positions) {
                if (segment[0] == new_food_x && segment[1] == new_food_y) {
                    on_snake = true
                    break
                }
            }
        } while (on_snake)

        this.food_position[0] = new_food_x
        this.food_position[1] = new_food_y
    }

    public func reset(): Unit {
        this.length = 1
        this.score = 0
        this.positions = ArrayList<ArrayList<Int64>>([ArrayList<Int64>([this.SCREEN_WIDTH / 2, this.SCREEN_HEIGHT / 2])])
        this.random_food_position()
    }

    public func eat_food(): Unit {
        // Increase length and score
        this.length = this.length + 1
        this.score = this.score + 100

        // Add new head at food position
        let new_head = ArrayList<Int64>([this.food_position[0], this.food_position[1]])
        this.positions.add(new_head, at: 0)

        // Generate new food position
        this.random_food_position()
    }
}

