        var values = ""
        var first = true
        for (entry in data.entries()) {
            if (!first) {
                keys = keys + ", "
                values = values + ", "
            }
            keys = keys + entry.key()
            values = values + "'" + entry.value() + "'"
            first = false
        }
        "INSERT INTO " + this.table_name + " (" + keys + ") VALUES (" + values + ");"
    }

    public func update(data: HashMap<String, String>, condition: String): String {
