        "INSERT INTO table1 (key1, key2) VALUES ('value1', 'value2');"
        */
        var keys = ""
        var values = ""
        let size = data.size
        var i = 0
        for (key in data.keys()) {
            keys = keys + key
            values = values + "'${data[key]}'"
            if (i != size - 1) {
                keys = keys + ", "
                values = values + ", "
            }
            i = i + 1
        }
        "INSERT INTO ${this.table_name} (${keys}) VALUES (${values});"
    }

