        */
        var set_clause = ""
        let size = data.size
        var i = 0
        for (key in data.keys()) {
            set_clause = set_clause + "${key} = '${data[key]}'"
            if (i != size - 1) {
                set_clause = set_clause + ", "
            }
            i = i + 1
        }
        "UPDATE ${this.table_name} SET ${set_clause} WHERE ${condition};"
    }

