        sort(sortedData)
        if (n % 2 == 1) {
            return Float64(sortedData[n / 2])
        } else {
            let mid1 = sortedData[n / 2 - 1]
            let mid2 = sortedData[n / 2]
            return Float64(mid1 + mid2) / 2.0
        }
    }

    public static func mode(data: ArrayList<Int64>): ArrayList<Int64> {
        /*
        calculates the mode of the given list.
        :param data: the given list, ArrayList<Int64>.
        :return: the mode of the given list, ArrayList<Int64>.
        >>> Statistics3.mode(ArrayList<Int64>([1, 2, 3, 3]))
        [3]

        */
        let freqMap = HashMap<Int64, Int64>()
        var maxCount = 0L

        // Count frequencies
        for (item in data) {
            let count = freqMap.get(item) ?? 0L
            let newCount = count + 1L
            freqMap.add(item, newCount)
            if (newCount > maxCount) {
                maxCount = newCount
            }
        }

        // Collect all elements with maximum frequency
        let result = ArrayList<Int64>()
        for (entry in freqMap.entries()) {
            if (entry.value == maxCount) {
                result.add(entry.key)
            }
        }

        sort(result)
        return result
    }

    public static func mean(data: ArrayList<Int64>): Option<Float64> {
        /*
        calculates the mean of the given list.
        :param data: the given list, ArrayList<Int64>.
        :return: the mean of the given list, Option<Float64>.
        >>> Statistics3.mean(ArrayList<Int64>([1, 2, 3]))
        Some<Float64>(2.0)

        */
        let n = data.size
        if (n == 0) {
            return None<Float64>
        }
        var sum = 0L
        for (item in data) {
            sum += item
        }
        return Some<Float64>(Float64(sum) / Float64(n))
    }

    public static func standard_deviation(data: ArrayList<Int64>): Option<Float64> {
        /*
        calculates the standard deviation of the given list.
        :param data: the given list, ArrayList<Int64>.
        :return: the standard deviation of the given list, Option<Float64>.
        >>> Statistics3.standard_deviation(ArrayList<Int64>([1, 2, 3]))
        Some<Float64>(1.0)

        */
        let n = data.size
        if (n < 2) {
            return None<Float64>
        }

        let meanVal = mean(data).getOrThrow()
        var sumSquaredDiff = 0.0
        for (item in data) {
            let diff = Float64(item) - meanVal
            sumSquaredDiff += diff * diff
        }
        let variance = sumSquaredDiff / Float64(n)
        return Some<Float64>(sqrt(variance))
    }

    public static func correlation(x: ArrayList<Int64>, y: ArrayList<Int64>): Option<Float64> {
        /*
        calculates the correlation of the given list.
        :param x: the given list, ArrayList<Int64>.
