        >>> Statistics3.correlation(ArrayList<Int64>([1, 2, 3]), ArrayList<Int64>([4, 5, 6]))
        Some<Float64>(1.0)

        */
        let n = x.size
        if (n != y.size || n < 2) {
            return None<Float64>
        }

        let meanX = mean(x).getOrThrow()
        let meanY = mean(y).getOrThrow()

        var sumXY = 0.0
        var sumXX = 0.0
        var sumYY = 0.0

        for (i in 0..n) {
            let dx = Float64(x[i]) - meanX
            let dy = Float64(y[i]) - meanY
            sumXY += dx * dy
            sumXX += dx * dx
            sumYY += dy * dy
        }

        if (sumXX == 0.0 || sumYY == 0.0) {
            return Some<Float64>(0.0)
        }

        return Some<Float64>(sumXY / sqrt(sumXX * sumYY))
    }

    public static func correlation_matrix(data: ArrayList<ArrayList<Int64>>): ArrayList<ArrayList<Float64>> {
