        */
        let n = data.size
        let matrix = ArrayList<ArrayList<Float64>>(n)

        for (i in 0..n) {
            let row = ArrayList<Float64>(n)
            for (j in 0..n) {
                if (i == j) {
                    row.add(1.0)
                } else {
                    let corr = correlation(data[i], data[j])
                    row.add(corr.getOrThrow())
                }
            }
            matrix.add(row)
        }
        return matrix
    }

    public static func z_score(data: ArrayList<Int64>): Option<ArrayList<Float64>> {
        /*
        calculates the z-score of the given list.
        :param data: the given list, ArrayList<Int64>.
        :return: the z-score of the given list, Option<ArrayList<Float64>>.
        >>> Statistics3.z_score(ArrayList<Int64>([1, 2, 3, 4]))
        Some<ArrayList<Float64>>([-1.161895003862225, -0.3872983346207417, 0.3872983346207417, 1.161895003862225])

        */
        let n = data.size
        if (n < 2) {
            return None<ArrayList<Float64>>
        }

        let meanVal = mean(data).getOrThrow()
        let stdDev = standard_deviation(data).getOrThrow()

        if (stdDev == 0.0) {
            return None<ArrayList<Float64>>
        }

        let result = ArrayList<Float64>()
        for (item in data) {
            result.add((Float64(item) - meanVal) / stdDev)
        }
        return Some<ArrayList<Float64>>(result)
    }
}

