        add_stock(stock)
        return true
    }

    public func sell_stock(stock: Stock): Bool {
        for (i in 0..portfolio.size) {
            let existing_stock = portfolio[i]
            if (existing_stock == stock) {
                if (existing_stock.quantity < stock.quantity) {
                    return false
                }
                let total_value = stock.price * Float64(stock.quantity)
                cash_balance = cash_balance + total_value
                existing_stock.quantity = existing_stock.quantity - stock.quantity
                if (existing_stock.quantity == 0) {
                    portfolio.remove(at: i)
                }
                return true
            }
        }
        return false
    }

