    }

    public func remove_stock(stock: Stock): Bool {
        for (i in 0..portfolio.size) {
            if (portfolio[i] == stock) {
                portfolio.remove(at: i)
                return true
            }
        }
        return false
    }

    public func buy_stock(stock: Stock): Bool {
        let cost = stock.price * Float64(stock.quantity)
        if (cost > cash_balance) {
            return false
        }
        cash_balance = cash_balance - cost
        // Check if stock with same name exists, if so update quantity and price
        for (s in portfolio) {
            if (s.name == stock.name) {
                s.quantity = s.quantity + stock.quantity
                s.price = stock.price
                return true
            }
        }
        // Otherwise, add new stock
        portfolio.add(Stock(stock.name, stock.price, stock.quantity))
        return true
    }

    public func sell_stock(stock: Stock): Bool {
        var index = -1
        var existing_stock: Stock? = null
        for (i in 0..portfolio.size) {
            if (portfolio[i].name == stock.name) {
                index = i
                existing_stock = portfolio[i]
                break
            }
        }

        if (existing_stock == null || existing_stock.quantity < stock.quantity) {
            return false
        }

        let revenue = stock.price * Float64(stock.quantity)
        cash_balance = cash_balance + revenue

        if (existing_stock.quantity == stock.quantity) {
            portfolio.remove(at: index)
        } else {
            existing_stock.quantity = existing_stock.quantity - stock.quantity
        }

        return true
    }

    public func get_stock_value(stock: Stock): Float64 {
        return stock.price * Float64(stock.quantity)
    }

    public func calculate_portfolio_value(): Float64 {
        var total = cash_balance
        for (stock in portfolio) {
            total = total + get_stock_value(stock)
