class TimeUtils {
    let datetime: DateTime

    public init() {
        this.datetime = DateTime.now()
    }

    public func get_current_time(): String {
        let dt = DateTime.now()
        return "${dt.hour.toString().padStart(2, '0')}:${dt.minute.toString().padStart(2, '0')}:${dt.second.toString().padStart(2, '0')}"
    }

    public func get_current_date(): String {
        let dt = DateTime.now()
        return "${dt.year.toString().padStart(4, '0')}-${dt.month.toString().padStart(2, '0')}-${dt.day.toString().padStart(2, '0')}"
    }

    public func add_seconds(seconds: Int64): String {
        let dt = DateTime.now().addSeconds(seconds)
        return "${dt.hour.toString().padStart(2, '0')}:${dt.minute.toString().padStart(2, '0')}:${dt.second.toString().padStart(2, '0')}"
    }

    public func string_to_datetime(string: String): DateTime {
        // Assuming format "yyyy-MM-dd HH:mm:ss"
        return DateTime.parse(string)
    }

    public func datetime_to_string(datetime: DateTime): String {
        return datetime.toString()
    }

    public func get_minutes(string_time1: String, string_time2: String): Int64 {
        let dt1 = DateTime.parse(string_time1)
        let dt2 = DateTime.parse(string_time2)
        let diffMillis = dt2.timestamp() - dt1.timestamp()
        let diffMinutes = diffMillis / 60000.0
        return round(diffMinutes) as Int64
    }

    public func get_format_time(year: Int64, month: Int64, day: Int64, hour: Int64, minute: Int64, second: Int64): String {
        let dt = DateTime.create(year, month, day, hour, minute, second)
        return dt.toString()
    }
}

