        :return: ArrayList<Int64>, representing the player's cards
        >>> game = TwentyFourPointGame()
        >>> game.get_my_cards()

        */
        this._generate_cards()
        return this.nums.clone()
    }

    public func answer(expression: String): Bool {
        /*
        Check if a given mathematical expression using the cards can evaluate to 24.
        :param expression: String, mathematical expression using the cards
        :return: Bool, true if the expression evaluates to 24, false otherwise
        >>> game = TwentyFourPointGame()
        >>> game.nums = [4, 3, 6, 6]
        >>> ans = "4*3+6+6"
        >>> ret = game.answer(ans)
        true
        */
        // First check if the expression uses exactly the cards we have
        if (!this._validate_expression(expression)) {
            return false
        }

        return this.evaluate_expression(expression)
    }

    public func evaluate_expression(expression: String): Bool {
        /*
        Evaluate a mathematical expression and check if the result is 24.
        :param expression: String, mathematical expression
        :return: Bool, true if the expression evaluates to 24, false otherwise
        >>> game = TwentyFourPointGame()
        >>> nums = [4, 3, 6, 6]
        >>> ans = "4*3+6+6"
        >>> ret = game.evaluate_expression(ans)
        true
        */
        try {
            let parser = Parser(expression)
            let result = parser.parse()
            return result == 24
        } catch e {
            return false
        }
    }

    private func _validate_expression(expression: String): Bool {
        // Create a frequency map of numbers in the expression
        let expr_nums = this._extract_numbers(expression)
        if (expr_nums.size != 4) {
            return false
        }

        // Create a frequency map of the game cards
        let card_counts = HashMap<Int64, Int64>()
        for (num in this.nums) {
            let count = card_counts.get(num) ?? 0
            card_counts.add(num, count + 1)
        }

        // Create a frequency map of numbers in expression
        let expr_counts = HashMap<Int64, Int64>()
        for (num in expr_nums) {
            let count = expr_counts.get(num) ?? 0
            expr_counts.add(num, count + 1)
        }

        // Check if both maps match
        if (card_counts.size != expr_counts.size) {
            return false
        }

        for (entry in card_counts.entries()) {
            let key = entry.key
            let count = entry.value
            let expr_count = expr_counts.get(key) ?? 0
            if (count != expr_count) {
                return false
            }
        }

        return true
    }

    private func _extract_numbers(expression: String): ArrayList<Int64> {
        let numbers = ArrayList<Int64>()
        var i = 0
        while (i < expression.size) {
            let ch = expression[i]
            if (ch.isAsciiNumber()) {
                var num_str = ""
                while (i < expression.size && expression[i].isAsciiNumber()) {
                    num_str += String(expression[i])
                    i += 1
                }
                numbers.add(Int64.parse(num_str))
            } else {
                i += 1
            }
        }
        return numbers
    }
}

