            let weight = log((total_num as Float64 + 1.0) / (count + 1.0))
            result.add(key, weight)
        }
        return result
    }

    // Helper function to compute dot product
    private static func dot(a: ArrayList<Float64>, b: ArrayList<Float64>): Float64 {
        var sum: Float64 = 0.0
        for (i in 0..a.size) {
            sum = sum + a[i] * b[i]
        }
        return sum
    }

    // Helper function to compute L2 norm
    private static func norm(vec: ArrayList<Float64>): Float64 {
        var sum_squares: Float64 = 0.0
        for (val in vec) {
            sum_squares = sum_squares + val * val
        }
