        var sum_squares: Float64 = 0.0
        for (val in vec) {
            sum_squares = sum_squares + val * val
        }
        return sqrt(sum_squares)
    }

    private static func average_vector(vectors: ArrayList<ArrayList<Float64>>): ArrayList<Float64> {
        let size = vectors.size
        if (size == 0) {
            return ArrayList<Float64>()
        }
        let dim = vectors[0].size
        let avg = ArrayList<Float64>(Array<Float64>(dim, 0.0))
        for (vec in vectors) {
            for (i in 0..dim) {
                avg[i] = avg[i] + vec[i]
            }
        }
        for (i in 0..dim) {
            avg[i] = avg[i] / (size as Float64)
        }
        return avg
    }
}

