        >>> weather_list['New York'] = Weather('sunny', 27.0, 'celsius')
        >>> weather_list['Beijing'] = Weather('cloudy', 23.0, 'celsius')
        >>> weatherSystem.query(weather_list)
        (27.0, 'sunny')

        */
        let weather_info = weather_list.get(this.city)
        if (weather_info is Some<Weather>) {
            let info = weather_info.getOrThrow()
            let temp = if (tmp_units == "celsius" && info.temperature_units == "fahrenheit") {
