                continue
            }

            let value = this.numwords[w] ?? (0i64, 0i64)
            let scale = value[0]
            let increment = value[1]

            if (scale > 1) {
                current = (current * scale) + increment
            } else {
                current += increment
            }

            // Handle scale words like hundred, thousand, million, etc.
            if (scale > 100) {
                result += current
                current = 0i64
            }
        }

        result += current
        return result.toString()
    }

